const contactRow=(l,v)=>`<div class="contact"><span class="l">${esc(l)}</span><span class="v">${esc(v)}</span><button class="copy" data-v="${esc(v)}">Copy</button></div>`;
const linkRow=(l,u)=>`<div class="contact"><span class="l">${esc(l)}</span><span class="v"><a href="${esc(u)}" target="_blank" rel="noopener">${esc(u.replace(/^https?:\/\//,''))}</a></span></div>`;
const srcList=arr=>`<div class="src">${arr.map(u=>Array.isArray(u)?`<div>· <a href="${esc(u[1])}" target="_blank" rel="noopener">${esc(u[0])}</a></div>`:`<div>· <a class="u" href="${esc(u)}" target="_blank" rel="noopener">${esc(u.replace(/^https?:\/\/(www\.)?/,'').slice(0,90))}</a></div>`).join('')}</div>`;
const tip=$('#tip');
function showTip(e,html){tip.innerHTML=html;tip.style.display='block';moveTip(e);}
function moveTip(e){const w=tip.offsetWidth,h=tip.offsetHeight;let x=e.clientX+14,y=e.clientY+14;if(x+w>window.innerWidth-8)x=e.clientX-w-14;if(y+h>window.innerHeight-8)y=e.clientY-h-14;tip.style.left=x+'px';tip.style.top=y+'px';}
