function bindTips(root){$$('[data-tip]',root).forEach(el=>{if(el.__t)return;el.__t=1;el.addEventListener('mouseenter',e=>showTip(e,el.dataset.tip));el.addEventListener('mousemove',moveTip);el.addEventListener('mouseleave',hideTip);el.addEventListener('focus',()=>{const r=el.getBoundingClientRect();showTip({clientX:r.left,clientY:r.bottom},el.dataset.tip);});el.addEventListener('blur',hideTip);});}
/* one line an analyst can paste into a report: the figure, its change, its sources with their addresses and the date the figures were checked */
function figureLine(label,value,change,srcs,flag){const s=(srcs||[]).map(x=>Array.isArray(x)?(x[1]?`${x[0]}, ${x[1]}`:x[0]):String(x||'')).filter(Boolean).join('; ');return `${label}: ${value}${change?` (${change})`:''}. Source: ${s||'as reported'}. Figures verified ${MARKET.verified}${flag?`, ${flag}`:''} (Subhasta).`;}
function openEvidence(k){const e=EVIDENCE[k];if(!e)return;openDrawer(esc(e.l),`<span class="money" style="font-size:22px">${esc(e.v)}</span>`,`<div class="quote">${esc(e.n)}</div><div class="sec"><span class="label">Sources</span>${srcList(e.s)}</div><div class="sec asof">Figures verified ${esc(MARKET.verified)}.</div><div class="sec"><button class="btn sm copy" data-v="${esc(figureLine(e.l,e.v,e.chg,e.s))}">Copy the figure with its source</button></div>`);}

/* ---------- charts ---------- */
/* the tooltip's text without its tags, for the aria-label of a chart mark (role=graphics-symbol, so the name is permitted): a screen reader hears what the pointer sees */
/* a tooltip's plain text, entities decoded: every caller escapes it once for its attribute (aria-label="${esc(tipText(tip))}") */
const tipText=h=>String(h||'').replace(/<[^>]+>/g,' ').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&amp;/g,'&').replace(/\s+/g,' ').trim();
/* grouped bars by year; o (optional): cols, step of the value axis ('auto' picks one), cur (the currency sign), label (the chart's name), note (the legend's last line), lastLabels (false: no value over the last year's bars) */
function groupedBars(years,series,o){o=o||{};const W=640,H=250,pl=42,pr=10,pt=14,pb=28;const iw=W-pl-pr,ih=H-pt-pb;const top=Math.max(...series.flatMap(s=>s[1].filter(v=>v!=null)));const step=o.step==='auto'?(top<=1?.25:top<=2.5?.5:top<=5?1:2):(o.step||2);const max=Math.max(step,Math.ceil(top/step)*step);const gw=iw/years.length;const bw=Math.min(22,(gw-12)/series.length);const cols=o.cols||['var(--c2)','var(--c3)','var(--c1)'];const cur=o.cur||'$';
  let g='';for(let k=0;k*step<=max+1e-9;k++){const v=Math.round(k*step*100)/100;const y=pt+ih-(v/max)*ih;g+=`<line x1="${pl}" x2="${W-pr}" y1="${y}" y2="${y}"/><text x="${pl-6}" y="${y+3}" text-anchor="end">${v}</text>`;}
  let bars='';years.forEach((yr,i)=>{const x0=pl+i*gw+(gw-bw*series.length-4*(series.length-1))/2;series.forEach((s,j)=>{const v=s[1][i];if(v==null)return;const h=(v/max)*ih,x=x0+j*(bw+4),y=pt+ih-h;const last=i===years.length-1&&o.lastLabels!==false;const tip=`<div class=k>${esc(s[0])}, ${yr}</div><div class=v>${esc(cur)}${v.toFixed(v<2?3:1)}bn</div>`;bars+=`<rect x="${x}" y="${y}" width="${bw}" height="${h}" rx="3" fill="${cols[j]}" tabindex="0" role="graphics-symbol" aria-label="${esc(tipText(tip))}" data-tip="${esc(tip)}"/>${last?`<text class="lbl" x="${x+bw/2}" y="${y-5}" text-anchor="middle">${v<2?v.toFixed(2):v.toFixed(1)}</text>`:''}`;});bars+=`<text x="${pl+i*gw+gw/2}" y="${H-8}" text-anchor="middle">${yr}</text>`;});
  return `<div class="chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(o.label||'Annual sales of the big three auction houses, 2019 to 2025, in US dollars billions')}"><g class="grid">${g}</g><g class="axis"><line x1="${pl}" x2="${W-pr}" y1="${pt+ih}" y2="${pt+ih}"/></g>${bars}</svg></div><div class="legend">${series.map((s,j)=>`<span><i style="background:${cols[j]}"></i>${esc(s[0])}</span>`).join('')}<span class="faint">${esc(o.note||'USD bn as reported; Phillips before 2024 approximate')}</span></div>`;}
function hbars(rows,fmt,cls,ev){const max=Math.max(...rows.map(r=>r[1]));return `<div class="bars">${rows.map(r=>`<div class="bar ${cls||''}" ${ev?`data-ev="${ev}"`:''}><span class="l" title="${esc(r[0])}">${esc(r[0])}</span><span class="tr"><span class="f" style="width:${(r[1]/max*100).toFixed(1)}%"></span></span><span class="v">${fmt(r)}</span></div>`).join('')}</div>`;}
function spark(series,w=120,h=34){if(!series||series.length<2)return '';const ys=series.map(s=>s[1]);const mn=Math.min(...ys)*0.85,mx=Math.max(...ys);const X=i=>4+(i/(series.length-1))*(w-8),Y=v=>h-4-((v-mn)/(mx-mn||1))*(h-8);const pts=series.map((s,i)=>`${X(i).toFixed(1)},${Y(s[1]).toFixed(1)}`);const area=`M${X(0)},${h-2} L${pts.join(' L')} L${X(series.length-1)},${h-2} Z`;const li=series.length-1;return `<svg viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" aria-hidden="true"><path d="${area}" fill="var(--gilt)" fill-opacity=".12"/><polyline points="${pts.join(' ')}" fill="none" stroke="var(--gilt)" stroke-width="1.6" stroke-linejoin="round"/><circle cx="${X(li)}" cy="${Y(series[li][1])}" r="2.6" fill="var(--gilt)"/></svg>`;}
function squarify(items,x,y,w,h){const out=[];const total=items.reduce((s,i)=>s+i.v,0);if(!total||w<=0||h<=0)return out;const scale=(w*h)/total;let rest=items.map(i=>({...i,a:i.v*scale}));let cx=x,cy=y,cw=w,ch=h;
  while(rest.length){const vert=cw<ch;const side=vert?cw:ch;let row=[],best=Infinity;
    for(let i=0;i<rest.length;i++){const cand=row.concat(rest[i]);const sum=cand.reduce((s,c)=>s+c.a,0);const mx=Math.max(...cand.map(c=>c.a)),mn=Math.min(...cand.map(c=>c.a));const worst=Math.max((side*side*mx)/(sum*sum),(sum*sum)/(side*side*mn));if(worst<=best){row=cand;best=worst;}else break;}
    const sum=row.reduce((s,c)=>s+c.a,0);const thick=sum/side;let off=0;row.forEach(c=>{const len=c.a/thick;if(vert)out.push({...c,x:cx+off,y:cy,w:len,h:thick});else out.push({...c,x:cx,y:cy+off,w:thick,h:len});off+=len;});
    if(vert){cy+=thick;ch-=thick;}else{cx+=thick;cw-=thick;}rest=rest.slice(row.length);}
  return out;}
function treemap(el){const W=el.clientWidth||1100,H=el.clientHeight||360;const pool=RESULTS.filter(r=>r.price>=20);const cats={};pool.forEach(r=>{(cats[r.cat]=cats[r.cat]||[]).push(r);});const groups=Object.entries(cats).map(([c,ls])=>({c,ls,v:ls.reduce((s,l)=>s+l.price,0)})).sort((a,b)=>b.v-a.v);
  const grects=squarify(groups,0,0,W,H);let html='';grects.forEach(g=>{const band=(g.h>46&&g.w>90)?20:0;const lots=[...g.ls].sort((a,b)=>b.price-a.price).map(l=>({v:l.price,l}));const rs=squarify(lots,g.x+1,g.y+band+1,Math.max(0,g.w-2),Math.max(0,g.h-band-2));
    rs.forEach(t=>{const r=t.l;const hc=['christies','sothebys','phillips'].includes(r.house)?r.house:'other';const lab=t.w>46&&t.h>26;const sz=!lab?'xs':((t.w<90||t.h<44)?'sm':'');const li=lotImg(r);const bgi=li&&t.w>=70&&t.h>=50?`background-image:url(img/t/${li.i}.jpg);`:'';html+=`<div class="tile h-${hc} ${sz} ${bgi?'img':''}" style="${bgi}left:${t.x.toFixed(1)}px;top:${t.y.toFixed(1)}px;width:${Math.max(0,t.w).toFixed(1)}px;height:${Math.max(0,t.h).toFixed(1)}px" data-lot="${r.id}" tabindex="0" role="button" ${lab?`aria-description="${esc(r.artist)}, ${esc(r.title)}, ${esc(houseName(r.house))}"`:`aria-label="${esc(r.artist)}, ${esc(r.title)}, ${mm(r.price)}, ${esc(houseName(r.house))}"`} data-tip="${esc(`<div class=k>${esc(r.artist)}, ${esc(r.title)}</div><div class=v>${mm(r.price)}</div><div>${esc(houseName(r.house))}, ${esc(r.city)}, ${esc(fdate(r.date))}</div>`)}">${lab?`<span class="n">${esc(dispName(r.artist))}</span><span class="p">${mm(r.price)}</span>`:''}</div>`;});
    if(band)html+=`<div class="tgroup" style="left:${g.x}px;top:${g.y}px;width:${g.w}px">${esc(g.c)} <span>${mm(g.v)}</span></div>`;});
  el.innerHTML=html;bindTips(el);bindLinks(el);}
/* ---------- price path ---------- */
function parseUSD(str){if(!str)return null;const m=str.match(/[≈~]?\$\s?([\d.,]+)\s*(bn|m|k)?/i);if(!m)return null;let v=parseFloat(m[1].replace(/,/g,''));if(isNaN(v))return null;const u=(m[2]||'').toLowerCase();if(u==='bn')v*=1e9;else if(u==='m')v*=1e6;else if(u==='k')v*=1e3;else if(v<1000&&!u)return null;return v;}
/* a price that covers several works ("$212,500 for fifteen works") is not this work's price: price paths and the Lab skip it */
const GROUP_PRICE=/\$\s?[\d.,]+\s*(?:bn|m|k)?\s+for (?:all |the whole )?(?:(?:two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|twenty|\d+) (?:works|paintings|pictures|canvases|panels)|the (?:series|group|set|pair))\b/i;
function parseYear(str){const m=(str||'').match(/(1[89]\d\d|20\d\d)/);return m?+m[1]:null;}
function pricePath(r,tall){if(!r.chain)return '';const pts=[];r.chain.forEach(c=>{if(GROUP_PRICE.test(`${c[1]} ${c[2]}`))return;const v2=parseUSD(c[2]);const v=v2||parseUSD(c[1]);const y=v2?(parseYear(c[0])||parseYear(c[1])):(parseYear(c[1])||parseYear(c[0]));if(y&&v)pts.push({y,v,l:c[1]});});const last={y:+r.date.slice(0,4),v:r.price*1e6,l:`${houseName(r.house)}, ${r.city}`};if(!pts.some(p=>p.y===last.y&&Math.abs(p.v-last.v)/last.v<0.02))pts.push(last);pts.sort((a,b)=>a.y-b.y);if(pts.length<2)return '';
  const W=640,H=tall?330:206,pl=tall?76:72,pr=24,pt=tall?34:32,pb=tall?40:38;   /* room on the left for “$100m” at phone size */const ys=pts.map(p=>p.y),vs=pts.map(p=>Math.log10(p.v));const y0=Math.min(...ys),y1=Math.max(...ys);const v0=Math.floor(Math.min(...vs)),v1=Math.ceil(Math.max(...vs));const X=y=>pl+((y-y0)/((y1-y0)||1))*(W-pl-pr),Y=v=>pt+(1-((Math.log10(v)-v0)/((v1-v0)||1)))*(H-pt-pb);
  let g='';for(let e=v0;e<=v1;e++){const yy=Y(Math.pow(10,e));const lab=e>=9?`$${Math.pow(10,e-9)}bn`:e>=6?`$${Math.pow(10,e-6)}m`:e>=3?`$${Math.pow(10,e-3)}k`:`$${Math.pow(10,e)}`;g+=`<line x1="${pl}" x2="${W-pr}" y1="${yy}" y2="${yy}"/>${v1-v0>5&&(v1-e)%2?'':`<text x="${pl-8}" y="${yy+3}" text-anchor="end">${lab}</text>`}`;}   /* more than five decades: every other one is labelled, so the scale stays legible on a phone */
  const path=pts.map((p,i)=>`${i?'L':'M'}${X(p.y).toFixed(1)},${Y(p.v).toFixed(1)}`).join(' ');const area=`${path} L${X(pts[pts.length-1].y).toFixed(1)},${H-pb} L${X(pts[0].y).toFixed(1)},${H-pb} Z`;
  /* two prices in the same year (or close years) sit on top of each other: the lower one's figure goes under its point, and a year is written once */
  const near=(i,j)=>j>=0&&j<pts.length&&Math.abs(X(pts[i].y)-X(pts[j].y))<50;
  const dots=pts.map((p,i)=>{const x=X(p.y),y=Y(p.v);const anchor=i===pts.length-1?'end':(i===0?'start':'middle');const under=[i-1,i+1].some(j=>near(i,j)&&pts[j].v>p.v);const yearAgain=i>0&&pts[i-1].y===p.y;const tip=`<div class=k>${p.y}</div><div class=v>${mm(p.v/1e6)}</div><div>${esc(p.l)}</div>`;return `<circle cx="${x}" cy="${y}" r="${tall?6:4.5}" fill="var(--gilt)" stroke="var(--ground)" stroke-width="2" ${tall?'':`tabindex="0" role="graphics-symbol" aria-label="${esc(tipText(tip))}" data-tip="${esc(tip)}"`}/><text class="lbl" x="${x}" y="${under?y+(tall?30:24):y-10}" text-anchor="${anchor}">${mm(p.v/1e6)}</text>${yearAgain?'':`<text x="${x}" y="${H-10}" text-anchor="${i===pts.length-1&&x>W-pr-24?'end':'middle'}">${p.y}</text>`}`;}).join('');
  const first=pts[0],fin=pts[pts.length-1];const mult=fin.v/first.v;const yrs=fin.y-first.y;const cagr=yrs>0?(Math.pow(mult,1/yrs)-1)*100:null;
  return `<div class="rh" style="margin-top:26px"><h2>Price path</h2><span class="sub">${mult>=2?`${mult>=100?Math.round(mult).toLocaleString('en-US'):mult.toFixed(1)}× in ${yrs} years${cagr!=null?`, ${cagr.toFixed(0)}% a year`:''}`:'reported prices on a log scale'}</span></div><div class="chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Reported prices of this work over time on a logarithmic scale"><g class="grid">${g}</g><path d="${area}" fill="var(--gilt)" fill-opacity=".1"/><path class="rline" d="${path}" fill="none" stroke="var(--gilt)" stroke-width="2" stroke-linejoin="round"/>${dots}</svg></div><div class="note">Log scale; points are prices reported in the ownership chain, with premium where published. Private-treaty prices are press reports.</div>`;}

/* ---------- hammer board ---------- */
const BOARD={items:[],i:0,timer:null};
function fit(s,n){s=(s||'').toUpperCase();if(s.length>n)s=s.slice(0,n-1)+'·';return s.padEnd(n,' ');}
const boardWidth=()=>window.innerWidth<480?20:(window.innerWidth<900?26:34);
function boardBuild(){const items=[...RESULTS].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,12);BOARD.items=items;const L=boardWidth();BOARD.L=L;const lines=[['l1',L,''],['l2',L,''],['l3',11,'money']];
  return `<div class="board" id="board"><div class="ttl"><span class="t">The hammer board: the latest marquee results, one lot at a time<span class="asof"> · as of ${esc(fdate(items[0]?items[0].date:TODAY))}, prices with premium</span></span><span class="n" id="bN">LOT 1 / ${items.length}</span></div>${lines.map(l=>`<div class="line ${l[2]==='money'?'price':''}" data-line="${l[0]}">${l[0]==='l1'?'<span class="sr" id="bSr"></span>':''}${Array.from({length:l[1]},()=>`<span class="fl ${l[2]}" aria-hidden="true">&nbsp;</span>`).join('')}</div>`).join('')}<div class="foot"><span id="bFoot"></span><span class="dots" id="bDots">${items.map((_,k)=>`<i class="${k===0?'on':''}"></i>`).join('')}</span></div></div>`;}
function boardShow(i){const r=BOARD.items[i];if(!r)return;BOARD.i=i;const reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;const texts={l1:`${dispName(r.artist)}  ${r.title}`,l2:`${houseName(r.house)}  ${r.city}  ${fdate(r.date)}`,l3:mm(r.price)};
  $$('#board .line').forEach(line=>{const cells=$$('.fl',line);const t=fit(texts[line.dataset.line],cells.length);cells.forEach((c,k)=>{const ch=t[k]===' '?' ':t[k];if(c.textContent===ch)return;if(reduce){c.textContent=ch;return;}setTimeout(()=>{c.classList.add('flip');setTimeout(()=>{c.textContent=ch;},170);setTimeout(()=>c.classList.remove('flip'),380);},k*22);});});
  const sr=$('#bSr');if(sr)sr.textContent=`Open the lot on the board: ${r.artist}, ${r.title}, ${houseName(r.house)}, ${mm(r.price)}`;
  $('#bN').textContent=`LOT ${i+1} / ${BOARD.items.length}`;$('#bFoot').innerHTML=`${r.rec.length?`<b>${esc(r.rec[0])}</b> · `:''}${esc(r.note||'')}`;$$('#bDots i').forEach((d,k)=>d.classList.toggle('on',k===i));}
function boardInit(){$$('#board .line').forEach((l,i)=>{l.addEventListener('click',()=>openLot(BOARD.items[BOARD.i]));if(i===0)keyable(l);else l.setAttribute('aria-hidden','true');});boardShow(0);clearInterval(BOARD.timer);const reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduce)BOARD.timer=setInterval(()=>{const f=$('#v-floor');if(document.hidden||!f||!f.classList.contains('on'))return;boardShow((BOARD.i+1)%BOARD.items.length);},7000);$$('#bDots i').forEach((d,k)=>d.addEventListener('click',()=>boardShow(k)));}

/* ---------- FLOOR ----------
   The front page is Today (src/today.js, pasted with the engines): renderFloor draws it. evTile stays here: the Pulse uses it too. */
/* a KPI tile drawn from the EVIDENCE entry it opens: v split into number and unit ($14.2 | bn), then d, chg and by */
function evTile(k){const e=EVIDENCE[k];const m=String(e.v).match(/^(\$?[\d.,]+)(.*)$/);const num=m?m[1]:e.v,unit=m?m[2]:'';return `<button class="kpi" data-ev="${k}"><div class="l">${esc(e.l)}</div><div class="v">${esc(num)}${unit?`<small>${esc(unit)}</small>`:''}</div><div class="d">${esc(e.d)} <b class="up">${esc(e.chg)}</b></div><div class="src">${esc(e.by)} · as of ${esc(MARKET.verified)}</div></button>`;}
/* ---------- HOUSES ---------- */
const TYPE_ORDER=['auction','gallery','advisory','finance','insurance','fair','data','logistics','freeport'];
const hstate={type:'all',q:'',sort:'sales'};
function salesVal(x){if(x.kind==='house'){const s=x.sales;if(s&&s.y25!=null)return s.cur==='€'?s.y25*1.08:s.y25;if(s&&s.y24!=null)return s.y24;}return -1;}
function renderHouses(){const el=$('#v-houses');el.innerHTML=`<div class="head"><div><h1>Houses and players</h1><p class="dek">Everyone who moves serious money in the trade: auction houses, galleries, advisors, lenders, insurers, fairs, data firms, shippers and freeports. Open any name for the dossier: history, leadership, scale, channels, how to approach.</p></div></div>
  <div class="toolbar"><input id="hq" type="search" placeholder="Search a name, a city, a person, a specialty" aria-label="Search directory" class="fill"><select id="hsort" aria-label="Sort"><option value="sales">By sales</option><option value="founded">By founding year</option><option value="name">By name</option></select><button class="btn" id="hcmpBtn" aria-expanded="false" aria-controls="hcmp">Compare houses</button><button class="btn" id="hcsv">Download CSV</button></div>
  <div class="hcmp" id="hcmp" hidden></div>
  <div class="chips" id="hchips" style="margin-bottom:18px"><button class="chip on" data-t="all">All</button>${TYPE_ORDER.map(k=>`<button class="chip" data-t="${k}">${esc(TYPES[k])}</button>`).join('')}</div>
  <div class="dirhead"><span></span><span>Organisation</span><span>Founded, headquarters</span><span>Latest sales</span><span>Leadership</span><span>Trend</span></div>
  <div class="dir" id="hdir"></div>`;
  $('#hq').addEventListener('input',e=>{hstate.q=norm(e.target.value.trim());drawDir();});$('#hsort').addEventListener('change',e=>{hstate.sort=e.target.value;drawDir();});
  $$('#hchips .chip').forEach(c=>c.addEventListener('click',()=>{$$('#hchips .chip').forEach(x=>x.classList.remove('on'));c.classList.add('on');hstate.type=c.dataset.t;drawDir();}));drawDir();
  $('#hcmpBtn').addEventListener('click',()=>houseCompareOpen($('#hcmp').hidden));$('#hcsv').addEventListener('click',()=>offerFile(`subhasta-directory-${TODAY}.csv`,directoryCSV(dirList()),'CSV'));if(store.get('houses.cmpOpen',false))houseCompareOpen(true,true);}
/* the searchable text of an organisation: name, type, city, founder, specialities or remit, leadership and known-for; not its URLs, figures or sources */
const orgText=x=>norm([x.name,TYPES[x.type],x.hq,x.hqAddress,x.rooms,x.founder,x.spec,x.known,x.lead,x.ownership,(x.leadership||[]).map(p=>p.join(' ')).join(' ')].filter(Boolean).join(' '));
/* the organisations the type chip and the search select, in the chosen order */
function dirList(){let list=ALL.filter(x=>hstate.type==='all'||x.type===hstate.type);if(hstate.q){const q=hstate.q;list=list.filter(x=>orgText(x).includes(q));}
  return list.sort((a,b)=>hstate.sort==='name'?a.name.localeCompare(b.name):hstate.sort==='founded'?(a.founded||9999)-(b.founded||9999):(salesVal(b)-salesVal(a))||(a.tier||9)-(b.tier||9)||TYPE_ORDER.indexOf(a.type)-TYPE_ORDER.indexOf(b.type)||a.name.localeCompare(b.name));}
function drawDir(){const list=dirList();
  $('#hdir').innerHTML=!list.length?'<div class="empty">No organisation matches. Try a name, a city or a specialty, or choose All.</div>':list.map(x=>{const h=x.kind==='house';const s=h?x.sales:null;const sales=h?(s.y25!=null?bn(s.y25,s.cur||'$'):(s.y24!=null?bn(s.y24,s.cur||'$'):'n/d')):'';const lead=h?x.leadership[0]:[(x.lead.match(/^([^,;(]+)/)||['',''])[1].trim(),''];
    return `<div class="org" data-org="${x.id}" tabindex="0" role="button"><div class="mono">${esc(x.name[0])}</div><div><div class="nm">${esc(x.name)}</div><div class="ty">${esc(TYPES[x.type])}${h&&x.tier?`, tier ${x.tier}`:''}${x.hq?`, ${esc(x.hq.split(' (')[0].split(' · ')[0])}`:''}</div></div><div class="f"><b>Founded</b>${esc(x.founded||'—')}, ${esc((h?x.hq:x.hq).split(' (')[0].split(' · ')[0])}</div><div class="f">${h?`<b>${esc(s.label)}${s.y25!=null?', 2025':s.y24!=null?', 2024':''}</b><span class="val">${esc(sales)}</span>${s.yoy&&s.yoy!=='n/a'?` <span class="${s.yoy.startsWith('+')?'up':s.yoy.startsWith('−')?'down':'faint'}">${esc(s.yoy)}</span>`:''}`:`<b>Scale</b>${esc((x.scale||'—').slice(0,70))}`}</div><div class="f"><b>${esc(h?lead[1].split(' (')[0]:'Lead')}</b>${esc(lead[0])}</div><div class="sp">${h&&x.series.length>1?spark(x.series,150,34):''}</div></div>`;}).join('');
  $$('#hdir .org').forEach(c=>{const open=()=>openOrg(c.dataset.org);c.addEventListener('click',open);c.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}});});}
/* ---------- houses side by side: two to four of the houses that report sales, by year; the selection is kept in store ('houses.cmp') ---------- */
const CMP_BIG3=['sothebys','christies','phillips'];
const cmpHouses=()=>HOUSES.filter(h=>h.series&&h.series.length).sort((a,b)=>salesVal(b)-salesVal(a));
let hcmpSel=(()=>{const ok=new Set(HOUSES.filter(h=>h.series&&h.series.length).map(h=>h.id));const s=(store.get('houses.cmp',null)||[]).filter(id=>ok.has(id)).slice(0,4);return s.length>=2?s:CMP_BIG3.slice();})();
/* sales in US$ bn: euro figures at the ECB rate the terminal uses (FX.eur), so shares can be compared */
const cmpUsdBn=(h,v)=>h.sales&&h.sales.cur==='€'?v*FX.eur:v;
function houseCompareModel(){const hs=hcmpSel.map(id=>HOUSES.find(h=>h.id===id)).filter(Boolean);const years=[...new Set(hs.flatMap(h=>h.series.map(p=>p[0])))].sort((a,b)=>a-b);
  const big=Object.fromEntries(years.map(y=>{const v=CMP_BIG3.map(id=>{const h=HOUSES.find(x=>x.id===id);const p=h&&h.series.find(q=>q[0]===y);return p?cmpUsdBn(h,p[1]):null;});return [y,v.every(x=>x!=null)?v.reduce((a,b)=>a+b,0):null];}));
  const cols=hs.map(h=>{const ser=h.series,last=ser[ser.length-1],prev=ser.length>1?ser[ser.length-2]:null;const by=Object.fromEntries(ser.map(p=>[p[0],p[1]]));const shY=[...ser].reverse().map(p=>p[0]).find(y=>big[y]);
    const yoy=h.sales.yoy&&h.sales.yoy!=='n/a'?h.sales.yoy:null;return {h,cur:h.sales.cur||'$',by,last,prev,yoy,yoyY:h.sales.y25!=null?2025:h.sales.y24!=null?2024:last[0],growth:prev?last[1]/prev[1]-1:null,shareY:shY||null,share:shY?cmpUsdBn(h,by[shY])/big[shY]:null};});
  return {hs,years,cols,big};}
function houseCompareRows(M){const pc=v=>v==null?'—':`${v>0?'+':v<0?'−':''}${Math.abs(v*100).toFixed(1)}%`;
  return [...M.years.map(y=>[String(y),...M.cols.map(c=>c.by[y]!=null?bn(c.by[y],c.cur):'—')]),['Latest change',...M.cols.map(c=>c.yoy?`${c.yoy} (${c.yoyY})`:c.growth==null?'—':`${pc(c.growth)} (${c.prev[0]}→${c.last[0]}, computed)`)],['Against the big three’s total',...M.cols.map(c=>c.share==null?'—':`${(c.share*100).toFixed(1)}% (${c.shareY})`)]];}
function drawHouseCompare(){const el=$('#hcmp');if(!el)return;const all=cmpHouses();const M=houseCompareModel();const rows=houseCompareRows(M);const n=hcmpSel.length;
  const COL={christies:'var(--c2)',sothebys:'var(--c3)',phillips:'var(--c1)'},spare=['var(--verd)','var(--cx)','var(--lapis)','var(--claret)'];let k=0;const cols=M.hs.map(h=>COL[h.id]||spare[k++%spare.length]);
  const oneCur=new Set(M.cols.map(c=>c.cur)).size===1;
  el.innerHTML=`<div class="rh"><h2>Houses side by side</h2><span class="sub">sales as each house reports them, by year · <button id="hcCopy">copy the table</button></span></div>
   <div class="chips hcpick" role="group" aria-label="Houses to compare, two to four">${all.map(h=>{const on=hcmpSel.includes(h.id);return `<button class="tag${on?' on':''}" data-hc="${h.id}" aria-pressed="${on}"${!on&&n>=4?' disabled':''}>${esc(h.name)}</button>`;}).join('')}<span class="faint hcn">${n<2?'pick at least two':n>=4?'four at most':'two to four'}</span></div>
   ${n<2?'<div class="empty">Pick at least two houses to set them side by side.</div>':`<div class="grid hcgrid"><div class="sect c7"><div class="tblwrap"><table class="tbl hctbl"><caption class="sr">Sales by year of ${esc(M.hs.map(h=>h.name).join(', '))}</caption><thead><tr><th scope="col">Year</th>${M.cols.map(c=>`<th scope="col" class="n">${esc(c.h.name)}<small>${esc(c.h.sales.label)}</small></th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr class="${i>=M.years.length?'sum':''}"><th scope="row">${esc(r[0])}</th>${r.slice(1).map(v=>`<td class="n${i<M.years.length?' money':''}">${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>
   <div class="sect c5">${oneCur?groupedBars(M.years,M.cols.map(c=>[c.h.name,M.years.map(y=>c.by[y]!=null?c.by[y]:null)]),{cols,step:'auto',lastLabels:false,cur:M.cols[0].cur,label:`Sales by year of ${M.hs.map(h=>h.name).join(', ')}, in ${M.cols[0].cur==='€'?'euro':'US dollar'} billions`,note:`${M.cols[0].cur==='€'?'€':'US$'} bn as each house reports it`}):'<div class="note">The chart needs one currency; the table gives each house in its own.</div>'}</div></div>
   <div class="note">Definitions differ (consolidated or global sales; auction and private), so the shares are indicative. The share sets a house’s latest year against the sum of Sotheby’s, Christie’s and Phillips in that year; euro figures are converted at €1 = $${FX.eur}. The change is the one each house reports; where none is reported it is computed from the series.</div>`}`;
  $$('#hcmp [data-hc]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.hc;hcmpSel=hcmpSel.includes(id)?hcmpSel.filter(x=>x!==id):[...hcmpSel,id].slice(0,4);store.set('houses.cmp',hcmpSel);drawHouseCompare();focusEl($(`#hcmp [data-hc="${id}"]`));}));
  const cp=$('#hcCopy');if(cp)cp.addEventListener('click',()=>{const M2=houseCompareModel();copyText(rowsTSV([['Year',...M2.cols.map(c=>`${c.h.name} (${c.h.sales.label})`)],...houseCompareRows(M2)]),cp);});
  bindTips(el);markScrollables(el);}
function houseCompareOpen(open,quiet){const el=$('#hcmp'),b=$('#hcmpBtn');if(!el||!b)return;el.hidden=!open;b.setAttribute('aria-expanded',String(open));b.classList.toggle('on',open);store.set('houses.cmpOpen',open);if(open){drawHouseCompare();if(!quiet)scrollToEl(el);}}
/* the directory as CSV: the current type and search, in the current order, with every reported year of sales */
function directoryCSV(list){const base=location.href.split('#')[0];const yrs=[...new Set(HOUSES.flatMap(h=>(h.series||[]).map(p=>p[0])))].sort((a,b)=>a-b);
  const rows=[['Name','Type','Founded','Headquarters','Leadership','Sales measure','Currency',...yrs.map(y=>`Sales ${y} (bn)`),'Change, latest year (as reported)','Scale','Website','Link']];
  list.forEach(x=>{const h=x.kind==='house';const s=h?x.sales:null;const ser=h?Object.fromEntries((x.series||[]).map(p=>[p[0],p[1]])):{};rows.push([x.name,TYPES[x.type]||x.type,x.founded||'',x.hq||'',h?(x.leadership||[]).map(p=>`${p[0]} (${p[1]})`).join('; '):(x.lead||''),h?s.label||'':'',h?(s.cur||'$'):'',...yrs.map(y=>ser[y]!=null?ser[y]:''),h&&s.yoy&&s.yoy!=='n/a'?s.yoy:'',h?'':(x.scale||''),x.web||'',base+'#house-'+x.id]);});
  return rowsCSV(rows);}
function openOrg(id){const x=byId(id);if(!x)return;if(x.kind==='house')openHouse(x);else openPlayer(x);}
function watchBtn(key,label){const on=watchlist.includes(key);return `<button class="btn star ${on?'on':''}" data-watch="${esc(key)}">${on?'★ Watching':'☆ Watch'}</button>`;}
function bindWatch(root){$$('[data-watch]',root).forEach(b=>b.addEventListener('click',()=>toggleWatch(b.dataset.watch,b)));}
function openHouse(x){const s=x.sales;const lots=RESULTS.filter(r=>r.house===x.id).sort((a,b)=>b.price-a.price);const tl=TIMELINES[x.id]||[];const stories=STORIES.filter(st=>st.players.includes(x.id));
  const html=`<div class="dossier">${back('houses','Houses and players')}<div class="top"><div class="mono lg">${esc(x.name[0])}</div><div><h1>${esc(x.name)}</h1><p class="dek">${esc(TYPES[x.type])}, founded ${esc(x.founded)} by ${esc(x.founder)}. ${esc(x.spec)}</p></div><div class="acts">${watchBtn('org:'+x.id)}<button class="btn primary" id="dAdd">Add to Desk</button></div></div>
  <div class="strip"><div><div class="l">${esc(s.label)}${s.y25!=null?', 2025':s.y24!=null?', 2024':''}</div><div class="v g">${s.y25!=null?bn(s.y25,s.cur||'$'):s.y24!=null?bn(s.y24,s.cur||'$'):'not published'}${s.yoy&&s.yoy!=='n/a'?` <small class="${s.yoy.startsWith('+')?'up':s.yoy.startsWith('−')?'down':''}">${esc(s.yoy)}</small>`:''}</div></div><div><div class="l">Previous year</div><div class="v">${s.y24!=null&&s.y25!=null?bn(s.y24,s.cur||'$'):'—'}</div></div><div><div class="l">Employees</div><div class="v">${esc(x.employees.split(' (')[0].split(' worldwide')[0])}</div></div><div><div class="l">Headquarters</div><div class="v">${esc(x.hq)}</div></div><div><div class="l">Ownership</div><div class="v" style="font-size:16px">${esc(x.ownership.split('.')[0].split(';')[0].slice(0,60))}</div></div></div>
  <div class="grid">
    <div class="sect c7">${x.series.length>1?`<div class="rh"><h2>Sales since ${esc(x.series[0][0])}</h2><span class="sub">${x.series.map(p=>`${p[0]} ${bn(p[1],s.cur||'$')}`).join(', ')}</span></div><div class="sparkbig">${spark(x.series,700,90)}</div>`:''}
      <div class="rh" style="margin-top:${x.series.length>1?22:0}px"><h2>The year in detail</h2></div><div class="quote">${esc(s.detail)}</div>
      <div class="rh" style="margin-top:26px"><h2>History</h2><span class="sub">key dates as recorded by the house and standard references</span></div><div class="timeline">${tl.map(t=>`<div class="tl"><span class="y">${esc(t[0])}</span><span class="e">${esc(t[1])}</span></div>`).join('')||'<div class="empty">No timeline for this house yet.</div>'}</div>
      <div class="rh" style="margin-top:26px"><h2>Results at ${esc(x.name)}</h2><span class="sub">${lots.length} lots in the hammer list</span></div><div class="lots">${lots.slice(0,12).map(r=>`<div class="lot" data-lot="${r.id}"><span class="no">${r.rank}</span><span><span class="t">${esc(r.title)}</span><div class="a">${esc(r.artist)}${r.year?`, ${esc(r.year)}`:''}</div><div class="m">${esc(r.city)}, ${esc(fdate(r.date))}${r.rec.length?` · ${esc(r.rec[0])}`:''}</div></span><span class="p">${mm(r.price)}</span></div>`).join('')||'<div class="empty">No marquee lots in the list for this house; see its website for results.</div>'}</div>
      ${stories.length?`<div class="rh" style="margin-top:26px"><h2>In the salon</h2></div>${stories.map(st=>`<div class="story" data-story="${st.id}"><div><h3>${esc(st.t)}</h3><p>${esc(st.dek)}</p></div></div>`).join('')}`:''}
    </div>
    <div class="sect c5">${HOUSEIMG[x.id]?figure(HOUSEIMG[x.id].i,HOUSEIMG[x.id].n)+'<div style="height:22px"></div>':''}
      <div class="rh"><h2>Facts</h2></div><div class="facts"><span class="l">Headquarters</span><span class="v">${esc(x.hqAddress)}</span><span class="l">Salerooms</span><span class="v">${esc(x.rooms)}</span><span class="l">Ownership</span><span class="v">${esc(x.ownership)}</span><span class="l">Employees</span><span class="v">${esc(x.employees)}</span><span class="l">Buyer’s premium</span><span class="v">${esc(x.fees)}</span></div>
      <div class="rh" style="margin-top:26px"><h2>Leadership, 2026</h2><span class="sub">names with a page open the person</span></div><div class="people">${x.leadership.map(p=>{const pp=PEOPLE.find(q=>q.n===p[0]);return `<div class="pr"><span>${pp?`<button data-person="${pp.id}" style="font:inherit;color:var(--gilt)">${esc(p[0])}</button>`:esc(p[0])}</span><span class="t">${esc(p[1])}</span></div>`;}).join('')}</div>
      <div class="rh" style="margin-top:26px"><h2>Official channels</h2></div>${x.contacts.map(c=>contactRow(c[0],c[1])).join('')}${linkRow('Website',x.web)}${x.links.map(l=>linkRow(l[0],l[1])).join('')}
      <div class="rh" style="margin-top:26px"><h2>Three things to know</h2></div><ul class="ul">${x.facts.map(f=>`<li>${esc(f)}</li>`).join('')}</ul>
      <div class="rh" style="margin-top:26px"><h2>How to approach</h2></div><div class="quote">${esc(x.approach)}</div>
      <div class="rh" style="margin-top:26px"><h2>Sources</h2></div>${srcList(x.sources)}<div style="margin-top:12px" class="linkrow"><a href="https://en.wikipedia.org/wiki/${encodeURIComponent(x.wiki.replace(/ /g,'_'))}" target="_blank" rel="noopener">Wikipedia</a><a href="${esc(x.web)}" target="_blank" rel="noopener">Website</a></div>
    </div></div></div>`;
  detail(html,'house-'+x.id);bindWatch($('#v-detail'));$('#dAdd').addEventListener('click',()=>addToPipeline({org:x.name,person:x.leadership[0][0],role:x.leadership[0][1]}));}
function openPlayer(x){const stories=STORIES.filter(st=>st.players.includes(x.id));const html=`<div class="dossier">${back('houses','Houses and players')}<div class="top"><div class="mono lg">${esc(x.name[0])}</div><div><h1>${esc(x.name)}</h1><p class="dek">${esc(TYPES[x.type])}, founded ${esc(x.founded)}, ${esc(x.founder)}. ${esc(x.known)}</p></div><div class="acts">${watchBtn('org:'+x.id)}<button class="btn primary" id="dAdd">Add to Desk</button></div></div>
  <div class="strip"><div><div class="l">Headquarters</div><div class="v" style="font-size:18px">${esc(x.hq.split(' (')[0])}</div></div><div><div class="l">Scale</div><div class="v" style="font-size:16px">${esc((x.scale||'not disclosed').slice(0,80))}</div></div><div><div class="l">Leadership</div><div class="v" style="font-size:16px">${esc(x.lead.split(';')[0].slice(0,90))}</div></div></div>
  <div class="grid"><div class="sect c7"><div class="rh"><h2>Facts</h2></div><div class="facts"><span class="l">Headquarters</span><span class="v">${esc(x.hq)}</span>${x.rooms&&x.rooms!=='—'?`<span class="l">Locations</span><span class="v">${esc(x.rooms)}</span>`:''}<span class="l">Ownership and leadership</span><span class="v">${esc(x.lead)}</span><span class="l">Scale</span><span class="v">${esc(x.scale||'—')}</span><span class="l">Known for</span><span class="v">${esc(x.known)}</span></div>
    <div class="rh" style="margin-top:26px"><h2>2025–26</h2></div><ul class="ul">${x.facts.map(f=>`<li>${esc(f)}</li>`).join('')}</ul>
    ${stories.length?`<div class="rh" style="margin-top:26px"><h2>In the salon</h2></div>${stories.map(st=>`<div class="story" data-story="${st.id}"><div><h3>${esc(st.t)}</h3><p>${esc(st.dek)}</p></div></div>`).join('')}`:''}</div>
    <div class="sect c5"><div class="rh"><h2>Official channels</h2></div>${linkRow('Website',x.web)}${x.contact?contactRow('Contact',x.contact):''}<div class="rh" style="margin-top:26px"><h2>Sources</h2></div>${srcList(x.src)}</div></div></div>`;
  detail(html,'house-'+x.id);bindWatch($('#v-detail'));$('#dAdd').addEventListener('click',()=>addToPipeline({org:x.name,person:(x.lead.match(/^([^,;(]+)/)||['',''])[1].trim(),role:''}));}

/* ---------- PEOPLE ---------- */
const pstate={g:'all',q:''};
function renderPeople(){const el=$('#v-people');el.innerHTML=`<div class="head"><div><h1>People</h1><p class="dek">${PEOPLE.length} people who run the trade: who holds which desk, how they got there, and the organisational channel to reach them. Titles as published by their firms or reported by the trade press; only work channels are listed.</p></div></div>
  <div class="toolbar"><input id="pq" type="search" class="fill" placeholder="Search a name, a title, a city, a remit" aria-label="Search people"><select id="pg" aria-label="Group"><option value="all">All groups</option>${Object.entries(PGROUPS).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></div>
  <div class="grid"><div class="sect c8" id="plist"></div><div class="sect c4"><div class="rh"><h2>Routes in</h2><span class="sub">careers, internships, press, client services</span></div>${ROUTES.map(r=>`<div class="sec" style="margin-top:14px"><div class="serif" style="font-size:19px;margin-bottom:4px">${esc(houseName(r.org))}</div>${r.items.map(i=>i[1].startsWith('http')?linkRow(i[0],i[1]):contactRow(i[0],i[1])).join('')}</div>`).join('')}<div class="note" style="margin-top:14px">Sotheby’s and Christie’s do not publish specialist e-mails; their directories list departments and regional offices. Phillips, Bonhams and the advisory firms publish organisational addresses, shown here as printed on their sites.</div></div></div>`;
  $('#pq').addEventListener('input',e=>{pstate.q=norm(e.target.value.trim());drawPeople();});$('#pg').addEventListener('change',e=>{pstate.g=e.target.value;drawPeople();});bindCopies(el);drawPeople();}
function drawPeople(){let list=PEOPLE.filter(p=>pstate.g==='all'||p.g===pstate.g);if(pstate.q)list=list.filter(p=>norm(`${p.n} ${p.t} ${p.city} ${p.remit} ${orgName(p.org)} ${p.note}`).includes(pstate.q));
  const groups={};list.forEach(p=>{const k=orgName(p.org);(groups[k]=groups[k]||[]).push(p);});
  $('#plist').innerHTML=`<div class="rh"><h2>${list.length} people</h2><span class="sub">grouped by organisation</span></div>`+Object.entries(groups).map(([org,ps])=>`<div class="label cap" style="margin:16px 0 4px">${esc(org)}</div>${ps.map(p=>`<div class="person" data-person="${p.id}" tabindex="0"><span class="n">${esc(p.n)}</span><span class="t">${esc(p.t)}</span><span class="c">${esc(p.city)}</span></div>`).join('')}`).join('')||'<div class="empty">No one matches.</div>';bindLinks($('#plist'));}
function openPerson(id){const p=PEOPLE.find(x=>x.id===id);if(!p)return;const org=byId(p.org);const peers=PEOPLE.filter(x=>x.org===p.org&&x.id!==id);const route=ROUTES.find(r=>r.org===p.org);
  const html=`<div class="dossier">${back('people','People')}<div class="top"><div class="mono lg">${esc(p.n[0])}</div><div><h1>${esc(p.n)}</h1><p class="dek">${esc(p.t)}, ${org?`<button data-org="${org.id}" style="font:inherit;color:var(--gilt)">${esc(org.name)}</button>`:esc(orgName(p.org))}. ${esc(p.remit)}.</p></div><div class="acts"><button class="btn primary" id="dAdd">Add to Desk</button></div></div>
  <div class="strip"><div><div class="l">City</div><div class="v" style="font-size:20px">${esc(p.city)}</div></div><div><div class="l">Group</div><div class="v" style="font-size:20px">${esc(PGROUPS[p.g])}</div></div>${p.since?`<div><div class="l">At the firm since</div><div class="v">${esc(p.since)}</div></div>`:''}</div>
  <div class="grid"><div class="sect c7"><div class="quote">${esc(p.note)}</div><div class="rh" style="margin-top:26px"><h2>How to reach the desk</h2></div>${p.email?contactRow('Published work e-mail',p.email):''}${linkRow('Listed at',p.url)}${route?route.items.filter(i=>!i[1].startsWith('http')).map(i=>contactRow(i[0],i[1])).join(''):''}<div class="note" style="margin-top:12px">Write to the organisational channel, name the person and one specific, recent thing their desk did. The Desk composer builds that note from the dossier.</div></div>
  <div class="sect c5">${peers.length?`<div class="rh"><h2>Colleagues at ${esc(orgName(p.org))}</h2></div>${peers.map(x=>`<div class="person" data-person="${x.id}" tabindex="0"><span class="n">${esc(x.n)}</span><span class="t">${esc(x.t)}</span><span class="c">${esc(x.city)}</span></div>`).join('')}`:''}${org?`<div class="rh" style="margin-top:26px"><h2>${esc(org.name)}</h2></div><div class="facts"><span class="l">Type</span><span class="v">${esc(TYPES[org.type])}</span><span class="l">Headquarters</span><span class="v">${esc(org.hq.split(' (')[0])}</span></div><div style="margin-top:12px"><button class="btn" data-org="${org.id}">Open the dossier</button></div>`:''}</div></div></div>`;
  detail(html,'person-'+id);$('#dAdd').addEventListener('click',()=>addToPipeline({org:orgName(p.org),person:p.n,role:p.t}));}
function openUpcoming(i){const u=UPCOMING[i];if(!u)return;const h=houseById(u.house);const body=`${UPIMG[u.title]?figure(UPIMG[u.title].i,UPIMG[u.title].n)+'<div style="height:16px"></div>':''}<div class="facts"><span class="l">${u.date<NOW?'Estimate before the sale':'Estimate'}</span><span class="v money" style="font-size:20px">${esc(u.est)}</span><span class="l">Sale</span><span class="v">${esc(h?h.name:u.house)}, ${esc(u.city)}, ${esc(fdate(u.date))}</span>${u.year?`<span class="l">Date of work</span><span class="v">${esc(u.year)}</span>`:''}</div><div class="sec quote">${esc(u.note)}</div>${u.chain?`<div class="sec"><span class="label">Ownership, as reported</span><div class="chain">${u.chain.map(c=>`<div class="ch"><span class="y">${esc(c[0])}</span><span class="w">${esc(c[1])}${c[2]?`<small>${esc(c[2])}</small>`:''}</span></div>`).join('')}</div></div>`:''}<div class="sec"><span class="label">Source</span>${srcList([u.src])}</div><div class="sec linkrow">${h?`<button class="btn sm" data-org="${h.id}">${esc(h.name)} dossier</button>`:''}<button class="btn sm" data-artist="${esc(u.artist)}">${esc(dispName(u.artist))} page</button></div>`;
  openDrawer(esc(u.title),`${esc(u.artist)} · ${u.date<NOW?`offered ${esc(fdate(u.date))}; the result comes with the refresh`:'coming to the block'}`,body);}

/* ---------- HAMMER ---------- */
/* the results table's sort keys, each with its heading and the direction it starts in; the reader's last sort is kept in store ('hammer.sort') */
const HAMMER_SORT={artist:['Artist, work','asc'],house:['House, city','asc'],date:['Date','desc'],cat:['Category','asc'],price:['Price','desc']};
const HAMMER_ERAS={'2026':'2026','2025':'2025','2020s':'2020–2024','2010s':'2010–2019',earlier:'Before 2010'};
const rstate=Object.assign({house:'all',cat:'all',city:'all',era:'all',q:'',qRaw:'',sort:'price',dir:'desc'},(s=>s&&HAMMER_SORT[s.k]?{sort:s.k,dir:s.d==='asc'?'asc':'desc'}:{})(store.get('hammer.sort',null)));
/* count, total, median and top of a list of lots (price: US$ m with premium) */
function lotSummary(list){const p=list.map(r=>r.price).sort((a,b)=>a-b),n=p.length;return {n,total:p.reduce((s,v)=>s+v,0),med:!n?0:n%2?p[(n-1)/2]:(p[n/2-1]+p[n/2])/2,top:list.reduce((m,r)=>!m||r.price>m.price?r:m,null)};}
/* an artist's sort key: the surname, as surname() reads it everywhere else, after any parenthesis (“Beeple (Mike Winkelmann)” sorts under B) */
const artistSortKey=a=>surname(String(a).replace(/\s*\([^)]*\)/g,'').trim());
/* the lots the current filters select, in the current order */
function hammerList(){let list=[...RESULTS];if(rstate.house!=='all')list=list.filter(r=>r.house===rstate.house);if(rstate.cat!=='all')list=list.filter(r=>r.cat===rstate.cat);if(rstate.city!=='all')list=list.filter(r=>r.city===rstate.city);
  if(rstate.era!=='all'){list=list.filter(r=>{const y=+r.date.slice(0,4);return rstate.era==='2026'?y===2026:rstate.era==='2025'?y===2025:rstate.era==='2020s'?(y>=2020&&y<=2024):rstate.era==='2010s'?(y>=2010&&y<=2019):y<2010;});}
  if(rstate.q)list=list.filter(r=>norm(`${r.artist} ${r.title} ${houseName(r.house)} ${r.city} ${r.note} ${r.rec.join(' ')} ${r.cat} ${(r.chain||[]).map(c=>c.join(' ')).join(' ')}`).includes(rstate.q));
  const by={price:(a,b)=>a.price-b.price,date:(a,b)=>a.date.localeCompare(b.date),artist:(a,b)=>artistSortKey(a.artist).localeCompare(artistSortKey(b.artist))||a.artist.localeCompare(b.artist),house:(a,b)=>houseName(a.house).localeCompare(houseName(b.house))||a.city.localeCompare(b.city),cat:(a,b)=>a.cat.localeCompare(b.cat)}[rstate.sort]||((a,b)=>a.price-b.price);
  const s=rstate.dir==='asc'?1:-1;return list.sort((a,b)=>s*by(a,b)||b.price-a.price||a.title.localeCompare(b.title));}
/* the active filters in words, for the summary line and its copy */
const hammerFilters=()=>[rstate.house!=='all'?houseName(rstate.house):'',rstate.city!=='all'?rstate.city:'',rstate.cat!=='all'?rstate.cat:'',rstate.era!=='all'?HAMMER_ERAS[rstate.era]:'',rstate.qRaw?`“${rstate.qRaw}”`:''].filter(Boolean).join(' · ');
function hammerSort(k){if(!HAMMER_SORT[k])return;if(rstate.sort===k)rstate.dir=rstate.dir==='asc'?'desc':'asc';else{rstate.sort=k;rstate.dir=HAMMER_SORT[k][1];}store.set('hammer.sort',{k:rstate.sort,d:rstate.dir});const sel=$('#rsort');if(sel)sel.value=rstate.sort;drawHammer();}
function hammerCopyLine(list){const S=lotSummary(list),A=lotSummary(RESULTS),f=hammerFilters();if(!S.n)return `Hammer, Subhasta (${fdate(TODAY)}): no lot in the list matches ${f||'the filters'}.`;const t=S.top;
  return `Hammer, Subhasta (${fdate(TODAY)}): ${S.n} of ${A.n} marquee lots${f?` (${f})`:''}; total ${mm(S.total)}, ${Math.round(S.total/A.total*100)}% of the list’s value; median ${mm(S.med)}; top ${t.artist}, ${t.title}, ${mm(t.price)} (${houseName(t.house)}, ${t.city}, ${fdate(t.date)}). Prices include buyer’s premium.`;}
function hammerCSV(list){const base=location.href.split('#')[0];const rows=[['Rank','Artist','Title','Year','Price (US$ m, incl. premium)','House','City','Date','Category','Records','Note','Link']];list.forEach(r=>rows.push([r.rank,r.artist,r.title,r.year||'',r.price,houseName(r.house),r.city,r.date,r.cat,r.rec.join('; '),r.note||'',base+'#lot-'+r.id]));return rowsCSV(rows);}
function renderHammer(){const el=$('#v-hammer');const cities=Object.entries(RESULTS.reduce((o,r)=>{o[r.city]=(o[r.city]||0)+1;return o;},{})).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]));el.innerHTML=`<div class="head"><div><h1>Hammer</h1><p class="dek">What sold, where, for how much, to whom when it is known: ${RESULTS.length} marquee lots since 1990, the records by category, and the private sales the trade talks about. Prices include buyer’s premium. ${limLink('lots','What this list cannot tell you')}</p></div></div>
  <div class="toolbar"><input id="rq" type="search" class="fill" placeholder="Artist, title, buyer, house or city" aria-label="Search results"><select id="rhouse" aria-label="House"><option value="all">All houses</option>${HOUSES.filter(h=>RESULTS.some(r=>r.house===h.id)).map(h=>`<option value="${h.id}">${esc(h.name)}</option>`).join('')}</select><select id="rcity" aria-label="City"><option value="all">All cities</option>${cities.map(([c,n])=>`<option value="${esc(c)}">${esc(c)} (${n})</option>`).join('')}</select><select id="rcat" aria-label="Category"><option value="all">All categories</option>${CATS.map(c=>`<option>${esc(c)}</option>`).join('')}</select><select id="rera" aria-label="Period"><option value="all">All years</option>${Object.entries(HAMMER_ERAS).map(([k,l])=>`<option value="${k}">${esc(l)}</option>`).join('')}</select><select id="rsort" aria-label="Sort">${Object.entries(HAMMER_SORT).map(([k,l])=>`<option value="${k}" ${rstate.sort===k?'selected':''}>By ${esc(l[0].split(',')[0].toLowerCase())}</option>`).join('')}</select></div>
  <div class="hsum"><p id="rsum" aria-live="polite"></p><div class="acts"><button class="btn sm" id="rCopy">Copy the line</button><button class="btn sm" id="rCsv">Download CSV</button></div></div>
  <div class="tblwrap"><table class="tbl" id="rtbl"></table></div>
  <div class="rh" style="margin-top:30px"><h2>Artists index</h2><span class="sub">every artist in the hammer list: lots, top price, records, ledger entries; click for the page</span></div><div class="tblwrap"><table class="tbl"><thead><tr><th>Artist</th><th class="n">Lots</th><th class="n">Top price</th><th>Records held</th><th class="n">Ledger</th><th>Houses</th></tr></thead><tbody>${[...new Set(RESULTS.map(r=>r.artist))].map(a=>{const ls=RESULTS.filter(r=>r.artist===a).sort((x,y)=>y.price-x.price);return {a,ls,top:ls[0].price,recs:ls.flatMap(l=>l.rec).filter(x=>/record/i.test(x)).length,nga:ngaFor(a).length,houses:[...new Set(ls.map(l=>houseName(l.house)))]};}).sort((x,y)=>y.top-x.top).map(x=>`<tr class="clk" data-artist="${esc(x.a)}"><td class="t" style="font-size:16px">${esc(x.a)}</td><td class="n">${x.ls.length}</td><td class="money">${mm(x.top)}</td><td class="faint">${x.recs?x.recs+(x.recs===1?' record':' records'):'—'}</td><td class="n">${x.nga||'—'}</td><td class="faint">${esc(x.houses.join(', '))}</td></tr>`).join('')}</tbody></table></div>
  <div class="grid" style="margin-top:30px"><div class="sect c7"><div class="rh"><h2>Records</h2><span class="sub">by category, as reported</span></div><div class="tblwrap"><table class="tbl"><thead><tr><th>Category</th><th>Work</th><th class="n">Price</th><th>Where, when</th></tr></thead><tbody>${RECORDS.map(r=>`<tr><td class="faint">${esc(r[0])}</td><td class="t" style="font-size:15px">${esc(r[1])}</td><td class="money">${esc(r[2])}</td><td class="faint">${esc(r[3])}</td></tr>`).join('')}</tbody></table></div></div>
  <div class="sect c5"><div class="rh"><h2>Private treaty</h2><span class="sub">reported prices; never confirmed by the parties</span></div><div class="lots">${PRIVATE_TREATY.sort((a,b)=>parseFloat(b.price.replace(/[^0-9.]/g,''))-parseFloat(a.price.replace(/[^0-9.]/g,''))).map(p=>`<div class="lot" style="cursor:default;grid-template-columns:minmax(0,1fr) auto"><span><span class="t" style="font-size:16px">${esc(p.work)}</span><div class="a">${esc(p.who)}, ${p.year}</div><div class="m">${esc(p.note)}</div></span><span class="p" style="font-size:17px">${esc(p.price)}</span></div>`).join('')}</div></div></div>`;
  $('#rq').addEventListener('input',e=>{rstate.qRaw=e.target.value.trim();rstate.q=norm(rstate.qRaw);drawHammer();});
  [['rhouse','house'],['rcity','city'],['rcat','cat'],['rera','era']].forEach(([id,k])=>$('#'+id).addEventListener('change',e=>{rstate[k]=e.target.value;drawHammer();}));
  $('#rsort').addEventListener('change',e=>{const k=e.target.value;if(!HAMMER_SORT[k])return;rstate.sort=k;rstate.dir=HAMMER_SORT[k][1];store.set('hammer.sort',{k,d:rstate.dir});drawHammer();});
  $('#rCopy').addEventListener('click',()=>copyText(hammerCopyLine(hammerList()),$('#rCopy')));$('#rCsv').addEventListener('click',()=>offerFile(`subhasta-hammer-${TODAY}.csv`,hammerCSV(hammerList()),'CSV'));
  bindLinks(el);drawHammer();}
/* a column heading that sorts: aria-sort on the active one; a second press reverses it */
const hammerTh=k=>{const on=rstate.sort===k,[label]=HAMMER_SORT[k];return `<th scope="col"${k==='price'?' class="n"':''}${on?` aria-sort="${rstate.dir==='asc'?'ascending':'descending'}"`:''}><button class="sortb${on?' on':''}" data-sort="${k}">${esc(label)}<span class="ar" aria-hidden="true">${on?(rstate.dir==='asc'?'↑':'↓'):'↕'}</span></button></th>`;};
function drawHammer(){const list=hammerList();const S=lotSummary(list),A=lotSummary(RESULTS),f=hammerFilters();
  $('#rsum').innerHTML=S.n?`<b>${S.n}</b> of ${A.n} lots${f?` <span class="f">(${esc(f)})</span>`:''} · total <span class="money">${mm(S.total)}</span>, ${Math.round(S.total/A.total*100)}% of the list’s value · median <span class="money">${mm(S.med)}</span> · top <button class="lnk" data-lot="${S.top.id}">${esc(S.top.artist)}, ${esc(S.top.title)}</button> <span class="money">${mm(S.top.price)}</span>`:`<b>0</b> of ${A.n} lots${f?` <span class="f">(${esc(f)})</span>`:''}: nothing matches; widen a filter.`;
  $('#rCsv').disabled=!S.n;
  $('#rtbl').innerHTML=`<caption class="sr">Marquee results${f?`: ${esc(f)}`:''}, by ${esc(HAMMER_SORT[rstate.sort][0].toLowerCase())}</caption><thead><tr><th scope="col" class="n">Rank</th>${['artist','house','date','cat','price'].map(hammerTh).join('')}</tr></thead><tbody>${list.map(r=>`<tr class="clk" data-lot="${r.id}"><td class="n faint">${r.rank}</td><td class="t"><span class="k">${esc(r.artist)}</span>${esc(r.title)}${r.year||r.rec.length||r.chain?`<span class="a">${r.year?esc(r.year):''}${r.rec.length?` <span class="tag rec">${esc(r.rec[0])}</span>`:''}${r.chain?' <span class="tag">provenance</span>':''}</span>`:''}<span class="mob">${esc(houseName(r.house))}, ${esc(r.city)} · ${esc(fdate(r.date))}</span></td><td class="faint">${esc(houseName(r.house))}, ${esc(r.city)}</td><td class="faint nw">${esc(fdate(r.date))}</td><td class="faint">${esc(r.cat)}</td><td class="money">${mm(r.price)}</td></tr>`).join('')}${list.length?'':'<tr><td colspan="6" class="faint">Nothing matches.</td></tr>'}</tbody>`;
  $$('#rtbl [data-sort]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();const k=b.dataset.sort;hammerSort(k);focusEl($(`#rtbl [data-sort="${k}"]`));}));
  bindLinks($('#rtbl'));bindLinks($('#rsum'));markScrollables($('#v-hammer'));}
function openLot(r){if(!r)return;const h=houseById(r.house);const others=RESULTS.filter(o=>o.artist===r.artist&&o!==r).sort((a,b)=>b.price-a.price);const nga=ngaFor(r.artist);const fees=h&&SCHED[h.id]?premium(h.id,r.price*1e6):null;const hammer=fees!=null?impliedHammer(h.id,r.price*1e6):null;
  const html=`<div class="dossier">${back('hammer','Hammer')}<div class="top"><div></div><div><h1>${esc(r.title)}</h1><p class="dek"><button data-artist="${esc(r.artist)}" style="font:inherit;color:var(--gilt)">${esc(r.artist)}</button>${r.year?`, ${esc(r.year)}`:''}. ${esc(r.cat)}. Rank ${r.rank} of ${RESULTS.length} in this list.</p></div><div class="acts">${watchBtn('lot:'+r.id)}</div></div>
  <div class="strip"><div><div class="l">Price with premium</div><div class="v g">${mm(r.price)}</div></div><div><div class="l">Sold at</div><div class="v" style="font-size:18px">${h?`<button data-org="${h.id}" style="font:inherit;color:inherit;text-decoration:underline dotted;text-underline-offset:3px">${esc(h.name)}</button>`:esc(r.house)}, ${esc(r.city)}</div></div><div><div class="l">Date</div><div class="v" style="font-size:18px">${esc(fdate(r.date))}</div></div>${hammer!=null?`<div><div class="l">Implied hammer (today’s schedule)</div><div class="v" style="font-size:18px">${mm(hammer/1e6)}<small> premium ${mm((r.price*1e6-hammer)/1e6)}</small></div>${+r.date.slice(0,4)<2026?`<div class="l" style="margin-top:4px">the premium was lower in ${esc(r.date.slice(0,4))}, so the real hammer was higher</div>`:''}</div>`:''}</div>
  <div class="grid"><div class="sect c7">${r.rec.length?`<div style="margin-bottom:14px">${r.rec.map(x=>`<span class="tag rec">${esc(x)}</span>`).join('')}</div>`:''}${r.note?`<div class="quote">${esc(r.note)}</div>`:''}
    <div class="rh" style="margin-top:26px"><h2>Ownership and prices</h2><span class="sub">${r.chain?'as reported':'chain not yet compiled'}</span></div>${r.chain?`<div class="chain">${r.chain.map(c=>`<div class="ch"><span class="y">${esc(c[0])}</span><span class="w">${esc(c[1])}${c[2]?`<small>${esc(c[2])}</small>`:''}</span></div>`).join('')}</div>`:`<div class="empty">The documented chain for this lot is not in the ledger yet. The sale note above gives the consignor or buyer where they were reported; the house catalogue carries the full provenance.</div>`}${pricePath(r)}
    ${others.length?`<div class="rh" style="margin-top:26px"><h2>Other ${esc(dispName(r.artist))} lots in the list</h2></div><div class="lots">${others.map(o=>`<div class="lot" data-lot="${o.id}"><span class="no">${o.rank}</span><span><span class="t">${esc(o.title)}</span><div class="m">${esc(houseName(o.house))}, ${esc(o.city)}, ${esc(fdate(o.date))}</div></span><span class="p">${mm(o.price)}</span></div>`).join('')}</div>`:''}
    ${nga.length?`<div class="rh" style="margin-top:26px"><h2>${esc(dispName(r.artist))} in the provenance ledger</h2><span class="sub">${nga.length} museum ownership histories</span></div>${nga.slice(0,4).map(n=>`<div class="prov" data-prov="${n.id}"><div class="t">${esc(n.t)}</div><div class="a">${esc(n.d)}, ${esc(n.m)}</div><div class="p">${esc(n.p)}</div></div>`).join('')}<div style="margin-top:10px"><button class="btn sm" data-artist="${esc(r.artist)}">All ${nga.length} records and links</button></div>`:''}</div>
    <div class="sect c5">${lotImg(r)?figure(lotImg(r).i,lotImg(r).x?'':lotImg(r).n):''}<div class="plate" style="${lotImg(r)?'margin-top:14px':''}"><div class="label cap">Catalogue plate</div><div class="serif" style="font-size:13px;letter-spacing:.14em;text-transform:uppercase;margin-top:8px">${esc(r.artist)}</div><div class="serif" style="font-size:26px;line-height:1.1;margin:4px 0 6px;font-style:italic">${esc(r.title)}</div><div class="muted" style="font-size:13px">${r.year?esc(r.year)+' · ':''}${esc(r.cat)}</div><div class="money" style="font-size:30px;margin-top:10px">${mm(r.price)}</div><div class="faint" style="font-size:12px">${esc(houseName(r.house))}, ${esc(r.city)}, ${esc(fdate(r.date))}</div><div class="linkrow" style="margin-top:12px"><a href="https://commons.wikimedia.org/w/index.php?search=${encodeURIComponent(r.artist+' '+r.title)}&ns6=1" target="_blank" rel="noopener">Images on Wikimedia Commons</a><a href="https://www.google.com/search?tbm=isch&q=${encodeURIComponent(r.artist+' '+r.title)}" target="_blank" rel="noopener">Image search</a></div></div><div class="rh" style="margin-top:26px"><h2>Open ${esc(dispName(r.artist))} elsewhere</h2><span class="sub">results, museums, references</span></div><div class="linkrow">${LINKS(r.artist,slug).map(l=>`<a href="${esc(l[1])}" target="_blank" rel="noopener">${esc(l[0])}</a>`).join('')}</div>
      ${h?`<div class="rh" style="margin-top:26px"><h2>${esc(h.name)}</h2></div><div class="facts"><span class="l">Buyer’s premium now</span><span class="v">${esc(h.fees)}</span><span class="l">Private sales</span><span class="v">${esc((h.leadership.find(p=>/private sales/i.test(p[1]))||['see dossier'])[0])}</span></div><div style="margin-top:12px"><button class="btn" data-org="${h.id}">Open the dossier</button></div>`:''}
      <div class="rh" style="margin-top:26px"><h2>Fee check</h2><span class="sub">the same ${esc(mm(r.price))} price split under each house’s 2026 schedule</span></div><div class="facts">${Object.keys(SCHED).map(k=>{const H=impliedHammer(k,r.price*1e6);return `<span class="l">${esc(houseName(k))}</span><span class="v num">hammer ${mm(H/1e6)} and premium ${mm((r.price*1e6-H)/1e6)}, ${(((r.price*1e6-H)/H)*100).toFixed(1)}% of the hammer</span>`;}).join('')}</div><div class="faint" style="font-size:12px;margin-top:8px">Illustrative: the price with premium, divided into hammer and premium as each house would charge it today. The schedule at the time of sale was different. ${limLink('lots','The limits')}</div><div style="margin-top:12px"><button class="btn sm" data-flowlot="${esc(r.id)}">Follow the money for this lot →</button></div></div></div></div>`;
  detail(html,'lot-'+r.id);bindWatch($('#v-detail'));$$('#v-detail [data-prov]').forEach(p=>{keyable(p);p.addEventListener('click',()=>openProv(NGA.find(n=>n.id===p.dataset.prov),''));});}
function openArtist(a){const lots=RESULTS.filter(r=>r.artist===a).sort((x,y)=>y.price-x.price);const nga=ngaFor(a);const chains=lots.filter(l=>l.chain);const dealers=DEALERS.map((d,i)=>{const f=dealerMatch(d);return [d,nga.filter(n=>f(ngaMain(n))).length,i];}).filter(x=>x[1]>0).sort((x,y)=>y[1]-x[1]||x[2]-y[2]).slice(0,8);
  const html=`<div class="dossier">${back('ledger','Ledger')}<div class="top"><div></div><div><h1>${esc(a)}</h1><p class="dek">${lots.length?(()=>{const S=lotSummary(lots);return lots.length===1?`One marquee lot in the hammer list, ${mm(S.top.price)}. `:`${lots.length} marquee lots in the hammer list: ${mm(S.total)} in all, median ${mm(S.med)}, top ${mm(S.top.price)}, sold ${esc(lots.map(l=>l.date.slice(0,4)).sort()[0])}–${esc(lots.map(l=>l.date.slice(0,4)).sort().pop())}. `;})():''}${nga.length?`${nga.length} ownership ${nga.length===1?'history':'histories'} in the ledger.`:''}</p></div><div class="acts">${watchBtn('artist:'+artistSlug(a))}</div></div>
  <div class="grid">${imgsFor(a).length?`<div class="sect c12"><div class="rh"><h2>In the public domain</h2><span class="sub">${imgsFor(a).length} ${imgsFor(a).length===1?'work':'works'}; click to enlarge</span></div><div class="gallery">${imgsFor(a).map(k=>`<a href="#" data-lb="${k}"><img src="img/t/${k}.jpg" alt="${esc(IMG[k].t)}" loading="lazy"><span>${esc(IMG[k].t)}, ${esc(IMG[k].y)}<br><i class="faint">${esc(IMG[k].c)}</i></span></a>`).join('')}</div></div>`:''}<div class="sect c7">${lots.length?`<div class="rh"><h2>At auction</h2></div><div class="lots">${lots.map(o=>`<div class="lot" data-lot="${o.id}"><span class="no">${o.rank}</span><span><span class="t">${esc(o.title)}</span><div class="m">${esc(houseName(o.house))}, ${esc(o.city)}, ${esc(fdate(o.date))}${o.rec.length?` · ${esc(o.rec[0])}`:''}</div></span><span class="p">${mm(o.price)}</span></div>`).join('')}</div>`:''}
    ${nga.length?(()=>{const sc=nga.filter(n=>/^(accounted|partly|quiet)$/.test(labpStatus(n.id))),op=sc.filter(n=>labpStatus(n.id)!=='accounted').length;return `<div class="rh" style="margin-top:${lots.length?26:0}px"><h2>Ownership histories</h2><span class="sub">National Gallery of Art, ${nga.length} works${sc.length?` · 1933–45: ${sc.length} in the research dates, ${op} open (<a href="#lab-provenance">how it is read</a>)`:''}</span></div>${nga.map(n=>`<div class="prov" data-prov="${n.id}"><div class="t">${esc(n.t)}</div><div class="a">${esc(n.d)}, ${esc(n.m)}${ledgerChip(n)}</div><div class="p">${esc(n.p)}</div></div>`).join('')}`;})():'<div class="empty">No museum provenance records for this artist in the ledger.</div>'}</div>
    <div class="sect c5"><div class="rh"><h2>Open elsewhere</h2></div><div class="linkrow">${LINKS(a,slug).map(l=>`<a href="${esc(l[1])}" target="_blank" rel="noopener">${esc(l[0])}</a>`).join('')}</div>
    ${dealers.length?`<div class="rh" style="margin-top:26px"><h2>Dealers in these chains</h2><span class="sub">histories whose main text names each; open one in the Ledger</span></div>${dealers.map(([d,c,i])=>`<div class="dealer" data-ldealer="${i}" title="The Ledger’s histories of ${esc(a)} that name ${esc(d[0])}"><span class="r"></span><span class="n"><b>${esc(d[0])}</b><small>${esc(d[2].split('.')[0])}</small></span><span class="c">${c}</span></div>`).join('')}`:''}
    ${chains.length?`<div class="rh" style="margin-top:26px"><h2>Documented chains</h2></div>${chains.map(l=>`<div class="lot" data-lot="${l.id}" style="grid-template-columns:minmax(0,1fr) auto"><span><span class="t">${esc(l.title)}</span><div class="m">${l.chain.length} steps</div></span><span class="p">${mm(l.price)}</span></div>`).join('')}`:''}</div></div></div>`;
  detail(html,'artist-'+artistSlug(a));bindWatch($('#v-detail'));$$('#v-detail [data-prov]').forEach(p=>{keyable(p);p.addEventListener('click',()=>openProv(NGA.find(n=>n.id===p.dataset.prov),''));});
  $$('#v-detail [data-ldealer]').forEach(el=>{keyable(el);el.addEventListener('click',()=>ledgerDealer(+el.dataset.ldealer,a));});}

/* ---------- fee schedules ---------- */
const SCHED={sothebys:[[2e6,.28],[8e6,.22],[Infinity,.15]],christies:[[2e6,.28],[8e6,.22],[Infinity,.15]],phillips:[[2e6,.29],[8e6,.22],[Infinity,.15]],bonhams:[[35e3,.30],[750e3,.28],[1.5e6,.25],[7.5e6,.21],[Infinity,.14]],heritage:[[Infinity,.25]]};
function premium(h,amt){let prev=0,fee=0;for(const [cap,r] of SCHED[h]){const slice=Math.max(0,Math.min(amt,cap)-prev);fee+=slice*r;prev=cap;if(amt<=cap)break;}return fee;}
function impliedHammer(h,total){let lo=0,hi=total;for(let i=0;i<40;i++){const mid=(lo+hi)/2;if(mid+premium(h,mid)>total)hi=mid;else lo=mid;}return lo;}

/* ---------- SIGNALS ---------- */
function renderSignals(){const el=$('#v-signals');const cal=[...CALENDAR].sort((a,b)=>a.d.localeCompare(b.d));const wire=NEWS.map(n=>n.dt).filter(Boolean).sort();const nWords=words(SIGNALS.length);
  el.innerHTML=`<div class="head"><div><h1>Signals</h1><p class="dek">${esc(nWords[0].toUpperCase()+nWords.slice(1))} readings of where the money is moving in 2026, with the evidence; the wire from the last three weeks; the calendar to June 2027; and the feeds to keep it current.</p></div></div>
  <div class="grid"><div class="sect c7"><div class="rh"><h2>Momentum</h2><span class="sub">direction and evidence, October 2026</span></div>${SIGNALS.map((s,si)=>`<div class="sig" id="sig-${si}" tabindex="-1"><div>${SIGIMG[s.t]?`<img src="img/t/${SIGIMG[s.t]}.jpg" alt="" loading="lazy" style="float:right;width:110px;height:78px;object-fit:cover;margin:0 0 8px 14px;border:1px solid var(--rule)">`:''}<h3>${esc(s.t)}</h3><p>${esc(s.p)}</p></div><span class="tag ${s.dir==='heat'?'heat':s.dir==='cool'?'cool':''}">${s.dir==='heat'?'heating':s.dir==='cool'?'cooling':'steady'}</span><div class="srcs">${s.s.map(x=>`<a href="${esc(x[1])}" target="_blank" rel="noopener">${esc(x[0])}</a>`).join('')}</div></div>`).join('')}</div>
  <div class="sect c5"><div class="rh"><h2>The wire</h2><span class="sub">${esc(fspan(wire[0],wire[wire.length-1]))}</span></div>${NEWS.map(n=>`<div class="wire"><span class="d">${esc(n.d)}</span><div><div class="h"><a href="${esc(n.u)}" target="_blank" rel="noopener">${esc(n.h)}</a></div><div class="s">${esc(n.s)}</div><div class="o">${esc(n.o)}</div></div></div>`).join('')}</div>
  <div class="sect c7"><div class="rh"><h2>Calendar</h2><span class="sub">October 2026 to June 2027</span></div>${cal.map((c,ci)=>`<div class="cal ${(c.e||c.d)<NOW?'past':''}" id="cal-${ci}"><span class="d">${esc(fspan(c.d,c.e))}</span><span class="n">${c.u?`<a href="${esc(c.u)}" target="_blank" rel="noopener" style="color:inherit">${esc(c.n)}</a>`:esc(c.n)}${c.sub?`<small>${esc(c.sub)}</small>`:''}${c.exp&&!/expected/i.test(c.sub||'')?`<small class="faint">expected, not yet announced</small>`:''}</span><span class="c">${esc(c.c)}, ${esc(c.city)}</span></div>`).join('')}</div>
  <div class="sect c5"><div class="rh"><h2>Feeds</h2><span class="sub">tested 1 October 2026</span></div>${FEEDS.map(f=>`<div class="contact"><span class="l" style="width:160px">${esc(f[0])}</span><span class="v" style="font-size:12px"><a href="${esc(f[1])}" target="_blank" rel="noopener">${esc(f[1].replace(/^https?:\/\//,''))}</a></span><span class="tag ${f[2]==='verified'?'rec':'ex'}" style="font-size:10.5px">${esc(f[2].split(/[\s,;]/)[0])}</span></div>`).join('')}<div class="note" style="margin-top:10px">Paste a feed into any reader. The houses publish no RSS; their newsrooms are linked.</div></div></div>`;}

/* ---------- LEDGER ---------- */
const lstate={q:'',dealer:null,artist:'all',prov:'all'};
/* one dealer's matcher, shared by the Ledger, the artist pages and the Lab's provenance reading: the key and its other spellings (DEALERS
   column 5, alt) as whole words in any case, after any longer name that merely contains the key (column 5, not: 'Lansdell K. Christie', a
   collector) is struck out. It reads a history's main text: the notes are commentary, not owners. */
const dealerEsc=s=>String(s).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const dealerFns=new Map();
function dealerMatch(d){let f=dealerFns.get(d);if(f)return f;const x=(d&&d[4])||{};const names=[d[3]].concat(x.alt||[]).filter(Boolean);
  const re=new RegExp('(?:^|[^\\wÀ-ÿ])(?:'+names.map(dealerEsc).join('|')+')(?![\\wÀ-ÿ])','i');const not=x.not&&x.not.length?new RegExp(x.not.map(dealerEsc).join('|'),'gi'):null;
  f=t=>{const s=String(t||'');return re.test(not?s.replace(not,' '):s);};f.names=names;dealerFns.set(d,f);return f;}
/* a Ledger record's main text, as the Lab reads it */
const ngaMain=n=>{const r=labpIndex().get(String(n.id));return r?r.main:labpMain(n.p);};
/* open the Ledger on one dealer and, from an artist's page, one artist; the other filters are cleared so the list is the one named */
function ledgerDealer(i,artist){go('ledger');lstate.q='';lstate.prov='all';lstate.artist=artist&&NGA_ARTISTS.includes(artist)?artist:'all';lstate.dealer=i;
  const la=$('#lartist'),lp=$('#lprov'),lq=$('#lq');if(la)la.value=lstate.artist;if(lp)lp.value='all';if(lq)lq.value=DEALERS[i][3];
  $$('#ldeal .dealer').forEach(x=>{const on=+x.dataset.k===i;x.classList.toggle('on',on);x.setAttribute('aria-pressed',String(on));});drawLedger();const r=$('#lres');if(r)scrollToEl(r);}
/* the Lab's 1933–45 reading on the Ledger: a filter and a chip per record (labpStatus in lab_prov.js) */
const LEDGER_PROV=[['all','Every record'],['open','Open in 1933–45'],['quiet','Quiet in 1933–45'],['partly','Partly accounted for'],['accounted','Accounted for'],['outside','Not in scope']];
const ledgerChip=n=>{const s=labpStatus(n.id);return s==='accounted'||s==='partly'||s==='quiet'?` <span class="tag lp-${s}" title="The Lab’s reading of the years 1933 to 1945">1933–45: ${s==='accounted'?'accounted for':s==='partly'?'partly accounted for':'quiet'}</span>`:'';};
function renderLedger(){const el=$('#v-ledger');el.innerHTML=`<div class="head"><div><h1>Ledger</h1><p class="dek">${NGA.length} ownership histories of works by ${NGA_ARTISTS.length} market-defining artists, from the National Gallery of Art’s open data (81,540 objects carry provenance text). Search a collector, a dealer or a city; click a dealer to see what passed through their hands; open any artist for lots, records and links.</p></div></div>
  <div class="toolbar"><input id="lq" type="search" class="fill" placeholder="Duveen, Rothschild, Paris, Knoedler, Kress, Rockefeller…" aria-label="Search provenance"><select id="lartist" aria-label="Artist"><option value="all">All artists</option>${NGA_ARTISTS.map(a=>`<option>${esc(a)}</option>`).join('')}</select><select id="lprov" aria-label="The years 1933 to 1945">${LEDGER_PROV.map(([v,l])=>`<option value="${v}">${esc(l)}</option>`).join('')}</select><button class="btn" id="lclear">Clear</button></div>
  <div class="grid"><div class="sect c7" id="lres"></div>
  <div class="sect c5"><div class="rh"><h2>Dealer lineage</h2><span class="sub">mentions across 81,540 provenance records</span></div><div id="ldeal">${DEALERS.map((d,i)=>`<div class="dealer" data-k="${i}" tabindex="0"><span class="r">${i+1}</span><span class="n"><b>${esc(d[0])}</b><small>${esc(d[2])}</small></span><span class="c">${d[1].toLocaleString()}</span></div>`).join('')}</div></div>
  <div class="sect c12"><div class="rh"><h2>Case files</h2><span class="sub">how six prices were made; more chains sit on each lot page</span></div><div class="grid">${PROV_CASES.map(c=>`<div class="c4"><div class="label cap">${esc(c.lesson)}</div><div class="serif" style="font-size:24px;line-height:1.1;margin:4px 0 2px">${esc(c.t)}</div><div class="muted" style="font-size:13px;margin-bottom:8px">${esc(c.a)}</div><div class="chain">${c.chain.map(s=>`<div class="ch" style="grid-template-columns:64px minmax(0,1fr)"><span class="y">${esc(s[0])}</span><span class="w">${esc(s[1])}${s[2]?`<small>${esc(s[2])}</small>`:''}</span></div>`).join('')}</div></div>`).join('')}</div></div></div>`;
  $('#lq').addEventListener('input',e=>{lstate.q=e.target.value.trim();lstate.dealer=null;$$('#ldeal .dealer').forEach(d=>{d.classList.remove('on');d.setAttribute('aria-pressed','false');});drawLedger();});
  $('#lartist').addEventListener('change',e=>{lstate.artist=e.target.value;drawLedger();});
  $('#lprov').addEventListener('change',e=>{lstate.prov=e.target.value;drawLedger();});
  $('#lclear').addEventListener('click',()=>{lstate.q='';lstate.dealer=null;lstate.artist='all';lstate.prov='all';$('#lq').value='';$('#lartist').value='all';$('#lprov').value='all';$$('#ldeal .dealer').forEach(d=>{d.classList.remove('on');d.setAttribute('aria-pressed','false');});drawLedger();});
  $$('#ldeal .dealer').forEach(d=>{const pick=()=>{const k=+d.dataset.k;const on=d.classList.contains('on');$$('#ldeal .dealer').forEach(x=>{x.classList.remove('on');x.setAttribute('aria-pressed','false');});lstate.dealer=on?null:k;lstate.q='';$('#lq').value=on?'':DEALERS[k][3];if(!on){d.classList.add('on');d.setAttribute('aria-pressed','true');}drawLedger();};keyable(d);d.setAttribute('aria-pressed','false');d.addEventListener('click',pick);});
  drawLedger();}
/* marks every occurrence of the query (a string, or a dealer's names) in the raw text, folded as the search folds it (case, ’, accents:
   "cezanne" marks Cézanne), then escapes each piece: a mark never lands inside an entity such as &amp; */
const foldCh=c=>c.toLowerCase().replace(/’/g,"'").normalize('NFD').replace(/[\u0300-\u036f]/g,'');
function hl(text,q){const t=String(text==null?'':text);const qs=(Array.isArray(q)?q:[q]).filter(Boolean).map(x=>norm(x)).filter(Boolean);if(!qs.length)return esc(t);
  let F='';const map=[];for(let i=0;i<t.length;i++){const f=foldCh(t[i]);for(let k=0;k<f.length;k++){F+=f[k];map.push(i);}}
  const re=new RegExp(qs.map(dealerEsc).join('|'),'g');let out='',last=0,m;
  while((m=re.exec(F))){if(!m[0].length){re.lastIndex++;continue;}const a=map[m.index],b=map[m.index+m[0].length-1]+1;if(a<last)continue;out+=esc(t.slice(last,a))+'<mark>'+esc(t.slice(a,b))+'</mark>';last=b;}
  return out+esc(t.slice(last));}
function drawLedger(){const dl=lstate.dealer!=null?DEALERS[lstate.dealer]:null;const q=dl?'':lstate.q;const hq=dl?dealerMatch(dl).names:q;let list=NGA;if(lstate.artist!=='all')list=list.filter(n=>n.a===lstate.artist);
  if(lstate.prov!=='all')list=list.filter(n=>{const s=labpStatus(n.id);return lstate.prov==='open'?(s==='partly'||s==='quiet'):lstate.prov==='outside'?(s==='outside'||s==='custody'):s===lstate.prov;});
  /* a dealer picked from the lineage is matched the way the Lab matches it; typed words are found anywhere in the record */
  if(dl){const f=dealerMatch(dl);list=list.filter(n=>f(ngaMain(n)));}else if(q){const ql=norm(q);list=list.filter(n=>(n.__s||(n.__s=norm(n.p+' '+n.t+' '+n.a+' '+n.cl))).includes(ql));} /* the normalised text of a record is kept on it after the first search */
  const pl=(LEDGER_PROV.find(x=>x[0]===lstate.prov)||[])[1];
  const head=`<div class="rh"><h2>${list.length} ${list.length===1?'record':'records'}${dl?` naming ${esc(dl[0])}`:q?` for “${esc(q)}”`:''}${lstate.artist!=='all'?`, ${esc(lstate.artist)}`:''}${lstate.prov!=='all'?`, ${esc(pl.charAt(0).toLowerCase()+pl.slice(1))}`:''}</h2><span class="sub">open a record for the full chain${dl?'; a dealer counts where the main text names it, the notes aside':''}${lstate.prov!=='all'?'; <a href="#lab-provenance">how 1933–45 is read</a>':''}</span></div>`;
  /* the row is the mouse target; the title is a real button for the keyboard, so the artist button inside is not nested in another control */
  const items=list.slice(0,80).map(n=>`<div class="prov" data-id="${n.id}"><button class="t" data-open="${n.id}">${hl(n.t,hq)}${n.img?' <span class="tag" style="font-size:10.5px">image</span>':''}</button><div class="a"><button data-artist="${esc(n.a)}" style="font:inherit;color:var(--gilt)">${hl(n.a,hq)}</button>, ${esc(n.d)}, ${esc(n.m)}${ledgerChip(n)}</div><div class="p">${hl(n.p,hq)}</div></div>`).join('');
  $('#lres').innerHTML=head+(items||'<div class="empty">No records match. Try a surname, a city or a dealer.</div>')+(list.length>80?`<div class="faint" style="padding-top:10px">Showing 80 of ${list.length}; narrow the search.</div>`:'');
  $$('#lres .prov').forEach(p=>{const open=()=>openProv(NGA.find(n=>n.id===p.dataset.id),hq);p.addEventListener('click',open);});bindLinks($('#lres'));}
function openProv(n,q){const lpn=labpNote(n.id);const prov=hl(n.p,q).replace(/\[(\d+)\]/g,'<sup>[$1]</sup>');const url=`https://www.nga.gov/collection/art-object-page.${n.id}.html`;const body=`<div class="facts"><span class="l">Artist</span><span class="v"><button data-artist="${esc(n.a)}" style="font:inherit;color:var(--gilt)">${esc(n.a)}</button></span><span class="l">Date</span><span class="v">${esc(n.d)}</span><span class="l">Medium</span><span class="v">${esc(n.m)}</span><span class="l">Credit line</span><span class="v">${esc(n.cl)}</span><span class="l">Accession</span><span class="v num">${esc(n.acc)}</span></div>
  ${lpn?`<div class="sec"><span class="label">1933 to 1945, as the Lab reads this text</span><p class="lp-note">${esc(lpn)} <button class="lnk" data-labhash="lab-provenance">How it is read</button></p></div>`:''}
  <div class="sec"><span class="label">Provenance, National Gallery of Art</span><div class="provfull">${prov}</div></div>
  <div class="sec linkrow"><a href="${url}" target="_blank" rel="noopener">Open at nga.gov</a>${n.img?`<a href="https://api.nga.gov/iiif/${esc(n.img)}/full/!1200,1200/0/default.jpg" target="_blank" rel="noopener">View the image (NGA open access)</a>`:''}</div>
  <div class="src" style="margin-top:14px">Source: National Gallery of Art Open Data (CC0), provenance text; bracketed numbers are the museum’s footnotes.</div>`;
  openDrawer(esc(n.t),`${esc(n.a)}, ${esc(n.d)}`,body);const lb=$('#dBody [data-labhash]');if(lb)lb.addEventListener('click',()=>{closeDrawer();openHashRoute(lb.dataset.labhash);});}

