async function postNote(){const t=$('#postText').value.trim();const st=$('#postStatus');if(!t){st.textContent='Write something first.';return;}if(!dbRef){st.textContent='Sign in to post.';return;}
  if(!myId){st.textContent='Sign in to post.';return;}const id='b'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);const mine=[{id,text:t.slice(0,1200),ts:Date.now(),tag:($('#postTag')||{}).value||'heard'},...(await ownBoard())].slice(0,50);try{await dbRef.collection('board').doc(myId).set({uid:myId,posts:mine});$('#postText').value='';st.textContent='Posted.';st.className='status ok';setTimeout(()=>{st.textContent='';},1500);}catch(e){st.textContent=e&&e.code==='not_granted'?'Viewers cannot post; contributors can.':'Could not post: '+((e&&e.code)||'error');st.className='status bad';}}

