const STATUS=[['s1','To contact'],['s2','Sent'],['s3','Replied'],['s4','Meeting'],['s5','Parked']];
let pipeline=[];let dbRef=null,userRef=null,sampleRef=null,dlRef=null,myId=null,watchlist=store.get('watch',[]);
/* a dossier drawn before the store answered shows the stars as they now are */
const refreshWatch=()=>$$('[data-watch]').forEach(b=>{const on=watchlist.includes(b.dataset.watch);b.classList.toggle('on',on);b.textContent=on?'★ Watching':'☆ Watch';});
const DEFAULT_BIO='Junior at George Washington University (International Business), president of the Russian Student Association, building open-data tools for the art market; aiming at private sales and collection management for ultra-high-net-worth clients.';
function renderDesk(){const el=$('#v-desk');el.innerHTML=`<div class="head"><div><h1>The desk</h1><p class="dek">Your workbench: a short, specific e-mail to a named person, built from the dossiers so every note mentions something true and recent; the pipeline of people you are writing to; what you are watching.</p></div><div class="status" id="deskStatus"></div></div>
  <div class="grid"><div class="sect c6"><div class="rh"><h2>Compose</h2><span class="sub">one ask, under 170 words</span></div><div class="form">
    <div class="two"><div><label for="cOrg">Organisation</label><select id="cOrg">${ALL.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div><label for="cIntent">Intent</label><select id="cIntent">${INTENTS.map(i=>`<option value="${i[0]}">${esc(i[1])}</option>`).join('')}</select></div></div>
    <div class="two"><div><label for="cPerson">Person</label><input id="cPerson" placeholder="Name, as on the team page"></div><div><label for="cRole">Their role</label><input id="cRole" placeholder="Vice Chairman, Head of Private Sales"></div></div>
    <div><label for="cAngle">Your angle: what you noticed, why them</label><textarea id="cAngle" placeholder="The $450m Blaquier-Arrieta consignment and how a house guarantee of that size is financed."></textarea></div>
    <div><label for="cBio">About you, two lines</label><textarea id="cBio">${esc(store.get('bio',DEFAULT_BIO))}</textarea></div>
    <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" id="cGen">Draft the e-mail</button><button class="btn" id="cRefine" hidden>Refine with Claude</button><button class="btn" id="cCopy">Copy draft</button><button class="btn" id="cAddPipe">Add to pipeline</button></div>
    <div class="draft" id="cDraft"><span class="faint">Choose a target and press Draft.</span></div></div></div>
  <div class="sect c6"><div class="rh"><h2>Pipeline</h2><span class="sub"><button id="pExport">Export CSV</button></span></div><div class="tblwrap"><table class="pipe" id="pipe"></table></div><div class="note" id="pNote" style="margin-top:10px"></div>
    <div class="rh" style="margin-top:26px"><h2>Watching</h2><span class="sub">stars from any dossier</span></div><div id="watching" class="lots"></div></div><div class="sect c12">${clinicHTML()}</div></div>`;initClinic();
  $('#cOrg').addEventListener('change',fillPerson);fillPerson();$('#cBio').addEventListener('input',e=>store.set('bio',e.target.value));
  $('#cGen').addEventListener('click',()=>showDraft(buildDraft()));$('#cCopy').addEventListener('click',()=>{const d=$('#cDraft').dataset.text;if(d)copyText(d);else toast('Draft first');});
  $('#cAddPipe').addEventListener('click',()=>addToPipeline({org:byId($('#cOrg').value).name,person:$('#cPerson').value,role:$('#cRole').value}));$('#cRefine').addEventListener('click',refineDraft);$('#pExport').addEventListener('click',exportPipeline);
  drawPipeline();drawWatching();if(sampleRef)$('#cRefine').hidden=false;}
/* the person: a house's first leader, or someone at the firm in People; otherwise left blank (the draft writes [name]). The role loses its
   bracketed notes ("(since Oct 2019)") and keeps its capitals */
const cleanRole=r=>String(r||'').replace(/\s*\([^)]*\)/g,'').replace(/\s*\([^)]*$/,'').split(';')[0].replace(/\s+/g,' ').trim();
function fillPerson(){const x=byId($('#cOrg').value);if(!x)return;const pp=PEOPLE.find(p=>p.org===x.id);
  if(x.kind==='house'&&x.leadership&&x.leadership[0]){$('#cPerson').value=x.leadership[0][0];$('#cRole').value=cleanRole(x.leadership[0][1]);}
  else if(pp){$('#cPerson').value=pp.n;$('#cRole').value=cleanRole(pp.t);}else{$('#cPerson').value='';$('#cRole').value='';}}
/* the salutation: "Dear Charles," for a first name; the whole name after a title (Sir, Dame, Dr, Baron…); [name] when the field holds no name */
/* British forms: Sir and Dame take the first name (Sir Nicholas); a professor, doctor or peer the surname (Professor Hanstein, Lord Browne);
   a Chinese name, family name first, is written whole (Hu Yanyan) */
const TITLE_FIRST=/^(Sir|Dame)$/,TITLE_LAST={'Prof.':'Professor',Prof:'Professor',Professor:'Professor','Dr':'Dr','Dr.':'Dr',Lord:'Lord',Lady:'Lady',Baron:'Baron',Baroness:'Baroness',Count:'Count',Countess:'Countess',Mr:'Mr',Mrs:'Mrs',Ms:'Ms',Sheikh:'Sheikh',Sheikha:'Sheikha'};
const CN_FAMILY=new Set('Hu Guo Li Wang Zhang Chen Liu Yang Zhao Huang Zhou Wu Xu Sun Ma Zhu Lin He Gao Luo Zheng Liang Xie Song Tang Han Feng Deng Cao Peng Zeng Xiao Tian Dong Yuan Pan Yu Jiang Cai Du Ye Cheng Wei Su Lu Ding Ren Shen Yao Qi Fu Kong'.split(' '));
const salute=person=>{const w=String(person||'').trim().split(/\s+/).filter(Boolean);if(!w.length)return '[name]';
  if(TITLE_FIRST.test(w[0])&&w[1])return `${w[0]} ${w[1]}`;if(TITLE_LAST[w[0]]&&w.length>1)return `${TITLE_LAST[w[0]]} ${w[w.length-1]}`;
  if(w.length>=2&&w.length<=3&&CN_FAMILY.has(w[0])&&/^[A-Z][a-z]+(?:-[a-z]+)?$/.test(w[1]))return w.join(' ');
  return /^[A-ZÀ-ÖØ-Þ][a-zß-öø-ÿ'’]+(?:-[A-ZÀ-ÖØ-Þa-zß-öø-ÿ][a-zß-öø-ÿ'’]+)*$/.test(w[0])?w[0]:'[name]';};
/* a fact that opens with its verb ("Moved into the Breuer building…") is about the firm: the hook names the firm as its subject, and calls it news only when the fact carries a date */
const VERB_START=/^(?:[A-Z][a-z]+ed|Sold|Bought|Took|Won|Lost|Became|Began|Made|Set|Held|Ran|Led|Grew|Fell|Rose|Paid|Left|Brought|Built|Kept|Spent|Went|Gave|Opened|Owns|Runs|Holds|Sells|Has|Is)\b/;
function buildDraft(){const x=byId($('#cOrg').value);const intent=$('#cIntent').value;const person=$('#cPerson').value.trim();const role=cleanRole($('#cRole').value);const angle=$('#cAngle').value.trim();const bio=$('#cBio').value.trim();const first=salute(person);const sur=norm(person.split(/\s+/).filter(Boolean).pop()||'');const fact=String(((x.facts||[]).find(f=>!(sur.length>2&&wordIn(norm(f),sur))))||'').trim();   /* not a fact that names the recipient: it would describe them to themselves */
  const lc=fact.charAt(0).toLowerCase()+fact.slice(1),dated=/\b(?:19|20)\d\d\b/.test(fact);
  const factLine=!fact?'':VERB_START.test(fact)?(dated?`I have been following ${x.name} closely, most recently the news that it ${lc}`:`I have been following ${x.name} closely; it ${lc}`):`I have been following ${x.name} closely. ${fact}`;
  const hook=angle||factLine||`I have been following ${x.name} closely.`;
  const asks={interview:`Would you have twenty minutes in the coming weeks for a short call? I would like to understand ${role?`what your work as ${role} involves day to day`:'how your side of the business works day to day'}, and what you would advise someone who wants to build a career in private sales and collection management.`,
    junior:`If ${x.name} takes interns or junior hires, in a specialist department or in client development, I would be grateful for a pointer to the right person or process. I can start part-time now and full-time from the summer.`,
    tool:`I built a research tool on the art market (house results, buyer’s premium schedules, a calendar, a provenance ledger on open museum data) and used it to prepare this note. If you have five minutes, I would value your reaction, especially to what a desk like yours would want it to do next.`,
    followup:`Thank you for your time at the recent sale. One question stayed with me: ${angle||'how the house decides between a guarantee and an irrevocable bid for a single-owner collection'}. If you have a moment, I would be glad to hear your view.`};
  const subjects={interview:`A question on private sales from a GW student (twenty minutes)`,junior:`Internship or junior role at ${x.name}`,tool:`An open-data research tool on the art market, for your reaction`,followup:`Thank you, and one question after the sale`};
  return {subject:subjects[intent],body:`Dear ${first},\n\n${hook}\n\n${asks[intent]}\n\n${bio}\n\nWith thanks and best regards,\nMikhail Tikhomirov\nGeorge Washington University, Washington, DC`};}
function showDraft(d){$('#cDraft').innerHTML=`<span class="subj">Subject: ${esc(d.subject)}</span>\n\n${esc(d.body)}`;$('#cDraft').dataset.text=`Subject: ${d.subject}\n\n${d.body}`;}
async function refineDraft(){if(!sampleRef)return;const t=$('#cDraft').dataset.text;if(!t){toast('Draft first');return;}const btn=$('#cRefine');btn.disabled=true;btn.textContent='Refining…';
  try{const out=await sampleRef.json(`You edit outreach e-mails for a university student approaching senior people in the art market. Rewrite the draft below. Rules: under 160 words; plain, specific English; one clear ask; keep every concrete fact; no flattery; no "I hope this finds you well"; keep the signature exactly. Return JSON with keys "subject" and "body".\n\nDRAFT:\n${t}`,{modelTier:'default'});if(out&&out.subject&&out.body){showDraft(out);toast('Refined');}else toast('Could not parse the answer');}
  catch(e){toast(e&&e.code==='not_granted'?'Claude access was not granted':'Refine failed');}finally{btn.disabled=false;btn.textContent='Refine with Claude';}}
function drawPipeline(){const t=$('#pipe');if(!t)return;const rows=[...pipeline].sort((a,b)=>(a.next||'9')>(b.next||'9')?1:-1);t.innerHTML=`<thead><tr><th>Target</th><th class="hide-sm">Person, role</th><th>Status</th><th>Next action</th><th class="hide-sm">Notes</th><th><span class="sr">Remove</span></th></tr></thead><tbody>${rows.map(r=>`<tr data-id="${esc(r.id)}"><td><b style="font-weight:500">${esc(r.org)}</b>${r.example?' <span class="tag ex" style="font-size:10.5px">example</span>':''}</td><td class="hide-sm">${esc(r.person)}${r.role?`<div class="faint" style="font-size:11.5px">${esc(r.role)}</div>`:''}</td><td><select data-f="status" aria-label="Status">${STATUS.map(s=>`<option value="${s[0]}" ${r.status===s[0]?'selected':''}>${s[1]}</option>`).join('')}</select></td><td><input type="date" data-f="next" value="${esc(r.next||'')}" aria-label="Next action date"></td><td class="hide-sm"><input data-f="notes" value="${esc(r.notes||'')}" placeholder="…" aria-label="Notes"></td><td><button class="copy" data-del="${esc(r.id)}" aria-label="Remove">✕</button></td></tr>`).join('')}${rows.length?'':'<tr><td colspan="6"><div class="empty">No targets yet. Open a dossier and press “Add to Desk”, or add from the composer.</div></td></tr>'}</tbody>`;
  $$('#pipe [data-f]').forEach(inp=>inp.addEventListener('change',()=>{const id=inp.closest('tr').dataset.id;const r=pipeline.find(p=>p.id===id);if(!r)return;r[inp.dataset.f]=inp.value;r.updated=new Date().toISOString();savePipe(r);}));
  $$('#pipe [data-del]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.del;if(b.dataset.armed){removePipe(id);}else{b.dataset.armed='1';b.textContent='Sure?';setTimeout(()=>{b.dataset.armed='';b.textContent='✕';},2500);}}));
  const n=$('#pNote');if(n)n.textContent=dbRef&&myId?'Private to you; saved in this page’s store and available on every device you sign in from.':canStore()?'Saved in this browser only.':'This browser blocks saving: the pipeline lasts until the page is closed.';}
function addToPipeline(t){const r={id:'p'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),org:t.org,person:t.person||'',role:t.role||'',status:'s1',next:'',notes:'',updated:new Date().toISOString()};pipeline.push(r);savePipe(r);drawPipeline();toast(`${t.org} added to the pipeline`);}
const pipeCol=()=>dbRef.collection('data/users/'+myId+'/desk/pipeline');
async function savePipe(r){if(dbRef&&myId){try{await pipeCol().doc(r.id).set(r);}catch(e){toast('Could not save: '+((e&&e.code)||'error'));}}else store.set('pipeline',pipeline);}
async function removePipe(id){pipeline=pipeline.filter(p=>p.id!==id);if(dbRef&&myId){try{await pipeCol().doc(id).delete();}catch(e){toast('Could not delete');}}else store.set('pipeline',pipeline);drawPipeline();}
async function exportPipeline(){const rows=[['Organisation','Person','Role','Status','Next action','Notes','Updated'],...pipeline.map(r=>[r.org,r.person,r.role,(STATUS.find(s=>s[0]===r.status)||['',''])[1],r.next||'',r.notes||'',r.updated||''])];await offerFile('subhasta-pipeline.csv',rowsCSV(rows),'CSV');}
function watchLabel(key){const [k,id]=key.split(':');if(k==='org'){const x=byId(id);return x?{n:x.name,s:TYPES[x.type],f:()=>openOrg(id)}:null;}if(k==='lot'){const r=lotById(id);return r?{n:r.title,s:`${r.artist}, ${mm(r.price)}`,f:()=>openLot(r)}:null;}if(k==='artist'){const a=artistBySlug(id);return a?{n:a,s:'artist',f:()=>openArtist(a)}:null;}if(k==='collector'){const c=COLLECTORS.find(x=>x.id===id);return c?{n:c.name,s:c.who,f:()=>openCollector(id)}:null;}return null;}
function drawWatching(){const el=$('#watching');if(!el)return;const items=watchlist.map(k=>({k,...(watchLabel(k)||{})})).filter(x=>x.n);el.innerHTML=items.map(x=>`<div class="lot" data-w="${esc(x.k)}" style="grid-template-columns:minmax(0,1fr) auto"><span><span class="t" style="font-size:16px">${esc(x.n)}</span><div class="m">${esc(x.s)}</div></span><span class="faint" style="font-size:12px">open</span></div>`).join('')||'<div class="empty">Nothing starred yet. Every house, lot, artist and collector page has a star.</div>';
  $$('#watching [data-w]').forEach(r=>{keyable(r);r.addEventListener('click',()=>{const l=watchLabel(r.dataset.w);if(l)l.f();});});}
async function toggleWatch(key,btn){const on=watchlist.includes(key);watchlist=on?watchlist.filter(k=>k!==key):[...watchlist,key];if(btn){btn.classList.toggle('on',!on);btn.textContent=on?'☆ Watch':'★ Watching';}
  if(dbRef&&myId){try{await dbRef.collection('data/users/'+myId).doc('watch').set({items:watchlist,updated:Date.now()});}catch(e){store.set('watch',watchlist);}}else store.set('watch',watchlist);drawWatching();}
async function initCaps(){if(!(window.claude&&window.claude.use))return finishCaps();
  /* the four capabilities are requested together; a host that answers none settles in one timeout, not four, and one refusal does not block the others */
  const use=n=>{try{return Promise.resolve(window.claude.use(n)).catch(()=>null);}catch(e){return Promise.resolve(null);}};
  [sampleRef,dlRef,dbRef,userRef]=await Promise.all(['sample','downloads','db','user'].map(use));
  if(sampleRef&&$('#cRefine'))$('#cRefine').hidden=false;
  try{if(userRef)myId=await userRef.id();}catch(e){}
  if(dbRef&&myId){try{pipeCol().onSnapshot(snap=>{const docs=(snap&&snap.docs)?snap.docs.map(d=>d.exists===false?null:(typeof d.data==='function'?d.data():d.data)):[];pipeline=docs.filter(x=>x&&x.id);drawPipeline();},()=>{dbRef=null;pipeline=store.get('pipeline',[]);drawPipeline();});}catch(e){dbRef=null;}}
  if(dbRef){try{dbRef.collection('board').onSnapshot(snap=>{const docs=(snap&&snap.docs)?snap.docs.map(d=>d.exists===false?null:{...(typeof d.data==='function'?d.data():d.data),_id:d.id}):[];const all=[];myBoard=null;docs.forEach(x=>{if(!x)return;if(Array.isArray(x.posts)){const uid=x._id;if(myId&&uid===myId)myBoard=x;x.posts.forEach(p=>{if(p&&p.text)all.push({...p,uid});});}else if(x.text)all.push({...x,uid:null});});   /* the author is board/<id>: the document id is spread last, so a uid or _id written in the body is ignored and no one can post under another member's name */posts=all.sort((a,b)=>(b.ts||0)-(a.ts||0)).slice(0,60);drawPosts();},()=>{posts=[];drawPosts();});}catch(e){}}
  if(dbRef){try{dbRef.collection('members').onSnapshot(snap=>{const docs=(snap&&snap.docs)?snap.docs.map(d=>d.exists===false?null:{...(typeof d.data==='function'?d.data():d.data),uid:d.id}):[];members=docs.filter(x=>x&&x.uid).sort((a,b)=>(b.ts||0)-(a.ts||0));   /* a card belongs to members/<id>, whatever its body says */drawMembers();const mine=members.find(m=>m.uid===myId);if(mine){const f=(id,v)=>{const e=$(id);if(e&&!e.value)e.value=v||'';};f('#mRole',mine.role);f('#mCity',mine.city);f('#mFocus',mine.focus);if($('#mOpen'))$('#mOpen').value=mine.open||'coffee';}},()=>{members=[];drawMembers();});}catch(e){}}
  if(dbRef&&myId){try{const snap=await dbRef.collection('data/users/'+myId).doc('watch').get();const d=snap&&snap.exists&&snap.data();if(d&&Array.isArray(d.items))watchlist=d.items;}catch(e){}}
  finishCaps();}
function finishCaps(){if(!dbRef){pipeline=store.get('pipeline',[]);watchlist=store.get('watch',[]);drawPipeline();drawPosts();drawMembers();}drawWatching();refreshWatch();const st=$('#deskStatus');if(st)st.textContent=(dbRef?'Store: connected':'Store: this browser only')+(sampleRef?'. Claude: available':'');const bs=$('#boardStatus');if(bs&&!dbRef)bs.textContent='the board needs the page’s store; open signed in to read and post';
  /* without the store nothing can be posted or saved: the forms say so instead of failing on the button */
  if(!dbRef){['#postText','#postTag','#postBtn','#mRole','#mCity','#mFocus','#mOpen','#mSave'].forEach(sel=>{const e=$(sel);if(e)e.disabled=true;});const ps=$('#postStatus');if(ps)ps.textContent='Posting needs the page opened signed in.';const ms=$('#mStatus');if(ms)ms.textContent='Cards need the page opened signed in.';}
  /* the Lab's two readings of the ledger are heavy and depend only on the data: computed once the page is idle, so the Ledger, the Circle and the Clinic open at once */
  const idle=window.requestIdleCallback||(f=>setTimeout(f,1500));idle(()=>{try{labpRead();labhRead();}catch(e){}});}

/* ---------- LEXICON & INSTRUMENTS ---------- */
function renderLexicon(){const el=$('#v-lexicon');el.innerHTML=`<div class="head"><div><h1>Lexicon and instruments</h1><p class="dek">The vocabulary of the rostrum, the anatomy of a sale, the fees in force with a calculator, the career map, and the data room of sources this tool is built from.</p></div></div>
  <div class="grid"><div class="sect c12"><div class="rh"><h2>Fee calculator</h2><span class="sub">what a buyer pays on a hammer price under each house’s 2026 schedule</span></div><div class="calc"><div class="form"><div><label for="calcAmt">Hammer price, USD</label><input id="calcAmt" type="number" min="1000" step="1000" value="2500000"></div><div><label for="calcSeller">Seller’s commission, % (negotiable; often zero on trophies)</label><input id="calcSeller" type="number" min="0" max="20" step="0.5" value="5"></div><div class="note">Marginal tiers: the first $2m at 28%, the next $6m at 22%, the rest at 15% (Sotheby’s and Christie’s); Phillips 29% on the first tier; Bonhams five tiers from 30% to 14%; Heritage set by category, 25% assumed.</div></div><div class="out" id="calcOut"></div></div></div>
  <div class="sect c7"><div class="rh"><h2>Glossary</h2><span class="sub"><input id="gq" type="search" placeholder="Filter terms" aria-label="Filter glossary" style="width:180px;padding:5px 9px"></span></div><div id="glist"></div></div>
  <div class="sect c5"><div class="rh"><h2>Anatomy of a sale</h2><span class="sub">consignment to settlement</span></div>${ANATOMY.map((s,i)=>`<div class="step"><span class="k">${i+1}</span><div><h3>${esc(s[0])}</h3><p>${esc(s[1])}</p></div></div>`).join('')}</div>
  <div class="sect c12"><div class="rh"><h2>Buyer’s premium in force</h2><span class="sub">all four major houses raised it in 2026</span></div><div class="fees">${FEES.map(f=>`<div class="fee"><h3>${esc(f.h)}</h3><div class="eff">${esc(f.eff)}</div>${f.t.map(t=>`<div class="tier"><span>${esc(t[0])}</span><b>${esc(t[1])}</b></div>`).join('')}</div>`).join('')}</div></div>
  <div class="sect c7"><div class="rh"><h2>Career map</h2><span class="sub">roles, what they do, how people get in</span></div>${CAREERS.map(c=>`<div class="role"><h3>${esc(c.r)}</h3><p class="w">${esc(c.w)}</p><div class="path"><b>Route in</b> ${esc(c.p)}</div></div>`).join('')}</div>
  <div class="sect c5"><div class="rh"><h2>Data room</h2><span class="sub">free and paid sources</span></div><div class="apis">${APIS.map(a=>`<div class="api"><span class="n"><a href="${esc(a[3])}" target="_blank" rel="noopener" style="color:inherit">${esc(a[0])}</a><small>${esc(a[1])}</small></span><span class="c ${a[2]}">${a[2]==='key'?'free key':a[2]}</span></div>`).join('')}</div></div></div>`;
  const drawG=q=>{const ql=(q||'').toLowerCase();$('#glist').innerHTML=GLOSSARY.filter(g=>!ql||(g[0]+' '+g[1]+' '+g[2]).toLowerCase().includes(ql)).map(g=>`<div class="gl"><div class="t">${esc(g[0])}<small>${esc(g[1])}</small></div><div class="d">${esc(g[2])}</div></div>`).join('')||'<div class="empty">No term matches.</div>';};
  $('#gq').addEventListener('input',e=>drawG(e.target.value));drawG('');
  const calc=()=>{const amt=Math.max(0,+$('#calcAmt').value||0);const sc=Math.max(0,+$('#calcSeller').value||0)/100;$('#calcOut').innerHTML=`<div class="row" style="border-top:0"><span class="faint">House</span><span class="faint">Premium</span><span class="faint">Buyer pays</span></div>`+Object.keys(SCHED).map(k=>{const p=premium(k,amt);return `<div class="row"><span class="h">${esc(houseName(k))}</span><span class="fee">${mm(p/1e6)} (${amt?(p/amt*100).toFixed(1):0}%)</span><span class="tot">${mm((amt+p)/1e6)}</span></div>`;}).join('')+`<div class="row"><span class="h">Seller receives</span><span class="fee">less ${(sc*100).toFixed(1)}% commission</span><span class="tot">${mm(amt*(1-sc)/1e6)}</span></div><div class="note" style="margin-top:8px">On a ${mm(amt/1e6)} hammer the house’s gross margin is the premium plus the seller’s commission: ${mm((premium('sothebys',amt)+amt*sc)/1e6)} at Sotheby’s rates.</div>`;};
  $('#calcAmt').addEventListener('input',calc);$('#calcSeller').addEventListener('input',calc);calc();}

/* ---------- engines ----------
   build.py pastes src/under.js, src/pulse.js, src/atlas.js and src/clinic.js here, in this order, inside this IIFE's scope.
   Anything an engine runs at load (its top-level consts: FLOW, PRESETS, LENS, REGION_BOX, LABEL_OFF, CLINIC_FLAGS…) may use only
   what is declared above this line ($, $$, esc, store, slug, norm, words, TODAY, the data globals) and nothing below it; a later
   const would be in its temporal dead zone and the page would throw at load. Function declarations hoist, so the engines' functions
   may call anything in the file. RENDER and window.__S below depend on the engines (renderPulse, renderAtlas, renderUndertow,
   flowModel, FLOW, fmtUSD, openAtlas, openSymptom, openHub, openSegment, miniWorld), so the four placeholders must stay above them. */
/*__UNDER__*/
/*__PULSE__*/
/*__ATLAS__*/
/*__CLINIC__*/
/*__GLOBE__*/
/*__CIRCLE__*/
/*__LAB__*/
