/* ---------- PALETTE ---------- */
let palIdx=[],palSel=0;
function buildIndex(){palIdx=[];VIEWS.forEach((v,i)=>palIdx.push({k:'Section',n:['The floor','Pulse','Atlas','Houses and players','People','Hammer','Signals','Ledger','Salon','Undertow','The desk','The Lab','Lexicon and instruments','The Circle'][i],sub:'',v:i<9?String(i+1):'',f:()=>go(v)}));palIdx.push({k:'Section',n:'The Reel',sub:'the week in full-screen cards',v:'',f:()=>openReelHere(0)});
  ALL.forEach(x=>palIdx.push({k:TYPES[x.type],n:x.name,sub:x.hq?x.hq.split(' (')[0].split(' · ')[0]:'',v:x.kind==='house'&&x.sales&&x.sales.y25!=null?bn(x.sales.y25,x.sales.cur||'$'):'',f:()=>openOrg(x.id)}));
  RESULTS.forEach(r=>palIdx.push({k:'Lot',n:`${r.artist}, ${r.title}`,sub:`${houseName(r.house)}, ${fdate(r.date)}`,v:mm(r.price),f:()=>openLot(r)}));
  ARTISTS.forEach(a=>palIdx.push({k:'Artist',n:a,sub:`${RESULTS.filter(r=>r.artist===a).length} lots, ${ngaFor(a).length} records`,v:'',f:()=>openArtist(a)}));
  PEOPLE.forEach(p=>palIdx.push({k:'Person',n:p.n,sub:`${p.t}, ${orgName(p.org)}`,v:p.city,f:()=>openPerson(p.id)}));
  UPCOMING.forEach((u,i)=>palIdx.push({k:'Upcoming',n:`${u.artist}, ${u.title}`,sub:`${houseName(u.house)}, ${fdate(u.date)}`,v:u.est,f:()=>{go('floor');openUpcoming(i);}}));
  COLLECTORS.forEach(c=>palIdx.push({k:'Collector',n:c.name,sub:c.who,v:'',f:()=>openCollector(c.id)}));
  STORIES.forEach(s=>palIdx.push({k:'Story',n:s.t,sub:s.dek.slice(0,60),v:'',f:()=>openStory(s.id)}));
  GLOSSARY.forEach(g=>palIdx.push({k:'Term',n:g[0],sub:g[1],v:'',f:()=>{go('lexicon');$('#gq').value=g[0];$('#gq').dispatchEvent(new Event('input'));}}));
  DEALERS.forEach((d,i)=>palIdx.push({k:'Dealer',n:d[0],sub:'provenance ledger',v:d[1].toLocaleString(),f:()=>ledgerDealer(i)}));
  const land=sel=>{const el=$(sel);if(el){scrollToEl(el);if(!el.hasAttribute('tabindex'))el.tabIndex=-1;focusEl(el);}};
  SIGNALS.forEach((s,i)=>palIdx.push({k:'Signal',n:s.t,sub:'',v:s.dir==='heat'?'heating':s.dir==='cool'?'cooling':'steady',f:()=>{go('signals');land('#sig-'+i);}}));
  const calS=[...CALENDAR].sort((a,b)=>a.d.localeCompare(b.d));CALENDAR.forEach(c=>palIdx.push({k:'Date',n:c.n,sub:c.city,v:fspan(c.d,c.e),f:()=>{go('signals');land('#cal-'+calS.indexOf(c));}}));
  ATLAS.forEach(a=>palIdx.push({k:a.kind==='case'?'Case':'Undercurrent',n:a.t,sub:a.st.map(stName).join(', '),v:a.kind==='case'?String(a.year):'',f:()=>{go('undertow');openAtlas(a.id);}}));
  STATIONS.forEach(st=>palIdx.push({k:'Station',n:st.n,sub:st.k,v:'',f:()=>{go('undertow');selectStation(st.id,true);scrollToEl($('#ring'));}}));
  SYMPTOMS.forEach(x=>palIdx.push({k:'Diagnosis',n:x.t,sub:x.ev[0].join(' '),v:'',f:()=>{go('pulse');openSymptom(x.id);}}));
  VITALS.forEach(x=>palIdx.push({k:'Vital sign',n:x.l,sub:x.read,v:x.v,f:()=>{go('pulse');openVital(x.id);}}));
  HUBS.forEach(x=>palIdx.push({k:'Hub',n:x.n,sub:x.c+' · '+REGIONS[x.r],v:x.share.split(' ·')[0],f:()=>{go('atlas');openHub(x.id);}}));
  SEGMENTS.forEach(x=>palIdx.push({k:'Segment',n:x.n,sub:SEGGROUPS[x.g],v:x.trend.split(';')[0].slice(0,18),f:()=>{go('atlas');openSegment(x.id);}}));
  FAIRS.forEach(x=>palIdx.push({k:'Fair',n:x.n,sub:x.city,v:fspan(x.d,x.e),f:()=>{go('atlas');openHub(x.hub);}}));
  INSTITUTIONS.forEach(x=>palIdx.push({k:'Institution',n:x.n,sub:x.city+' · '+x.who,v:String(x.opened),f:()=>{go('atlas');openInstitution(x.id);}}));
  REPORTS.forEach((x,i)=>palIdx.push({k:'Report',n:x.n,sub:x.by,v:'next '+x.next,f:()=>{go('pulse');land('#rep-'+i);}}));
  /* the Lab's five instruments (the router opens #lab-<id> at the instrument), the journeys of the Undertow and the Brief of the Circle */
  /* the Lab's instruments as LAB_INSTR names them (lab.js), each with the words a reader might type */
  const LAB_PALSUB={returns:'returns',roundtrip:'round trip',structure:'structure',provenance:'provenance reading',hands:'holding periods, the founders’ dealers',confidence:'confidence'};
  LAB_INSTR.forEach(([id,n])=>palIdx.push({k:'Instrument',n,sub:'Lab · '+(LAB_PALSUB[id]||id),v:'',f:()=>openHashRoute('lab-'+id)}));
  JOURNEYS.forEach(j=>{const p=j.steps.filter(s=>s.usd);palIdx.push({k:'Journey',n:j.t,sub:j.a,v:p.length>=2?`${p[0].p} → ${p[p.length-1].p}`:'',f:()=>{go('undertow');const el=$('#journey-'+j.id);if(el){scrollToEl(el);focusEl(el);}}});});
  if(typeof CIRCLE==='object'&&CIRCLE&&CIRCLE.brief)palIdx.push({k:'Brief',n:CIRCLE.brief.n,sub:CIRCLE.brief.sub||'',v:'',f:()=>{go('circle');const el=$('#ci-brief');if(el){scrollToEl(el);focusEl(el);}}});
  palIdx.forEach(x=>{x.s=norm(x.n+' '+x.sub+' '+x.k);});} /* the normalised search text, computed once */
let palOpener=null;
function openPalette(){const p=$('#pal');if(!p.classList.contains('on'))palOpener=rememberOpener(p);p.classList.add('on');const i=$('#palq');i.value='';palSearch('');focusEl(i);setTimeout(()=>{if(p.classList.contains('on'))focusEl(i);},20);}
function closePalette(){const p=$('#pal');if(!p.classList.contains('on'))return;p.classList.remove('on');const o=palOpener;palOpener=null;returnFocus(o);}
function palSearch(q){const ql=norm(q.trim());let res=ql?palIdx.filter(x=>x.s.includes(ql)):palIdx.slice(0,8);res=res.slice(0,14);palSel=0;$('#palres').innerHTML=res.map((x,i)=>`<div class="ri ${i===0?'on':''}" data-i="${i}" id="palr-${i}" role="option" aria-selected="${i===0}"><span class="k">${esc(x.k)}</span><span class="n">${esc(x.n)}${x.sub?`<small>${esc(x.sub)}</small>`:''}</span><span class="v">${esc(x.v)}</span></div>`).join('')||'<div class="ri" role="option" aria-disabled="true" aria-selected="false"><span class="k"></span><span class="n faint">Nothing found</span></div>';$('#palres').dataset.res=JSON.stringify(res.map(x=>palIdx.indexOf(x)));
  $$('#palres .ri[data-i]').forEach(r=>r.addEventListener('click',()=>palPick(+r.dataset.i)));palMark();markScrollables($('#pal'));}
/* the highlighted row is the input's active descendant, so a screen reader announces it while focus stays in the field */
function palMark(){const rows=$$('#palres .ri[data-i]');rows.forEach((r,k)=>{r.classList.toggle('on',k===palSel);r.setAttribute('aria-selected',k===palSel?'true':'false');});const i=$('#palq');if(rows[palSel])i.setAttribute('aria-activedescendant',rows[palSel].id);else i.removeAttribute('aria-activedescendant');}
function palPick(i){const ids=JSON.parse($('#palres').dataset.res||'[]');const item=palIdx[ids[i]];if(!item)return;closePalette();item.f();}
function initPalette(){buildIndex();$('#palBtn').addEventListener('click',openPalette);$('#pal').addEventListener('click',e=>{if(e.target===$('#pal'))closePalette();});const i=$('#palq');i.addEventListener('input',e=>palSearch(e.target.value));
  i.addEventListener('keydown',e=>{const rows=$$('#palres .ri[data-i]');if(e.key==='ArrowDown'){e.preventDefault();palSel=Math.min(rows.length-1,palSel+1);}else if(e.key==='ArrowUp'){e.preventDefault();palSel=Math.max(0,palSel-1);}else if(e.key==='Enter'){e.preventDefault();palPick(palSel);return;}else return;palMark();});}

