let guideShown=false;function firstVisit(){if(guideShown||store.get('seen',false))return;if(window.__REEL&&window.__REEL.isOpen())return;guideShown=true;const g=document.createElement('div');g.className='guide';g.innerHTML=`<div class="gbox" role="dialog" aria-modal="true" aria-labelledby="guideTitle"><div class="label cap">New here</div><h3 id="guideTitle">Subhasta is the art trade’s terminal</h3><p>Start with the <b>Reel</b> for the pictures and the prices, read the <b>Pulse</b> for the diagnosis of the market, open the <b>Atlas</b> for your city’s rules, and choose a <b>lens</b> so the terminal reads for you. Every number opens its source; what we could not verify says so.</p><div class="chips"><button class="btn primary" data-g="reel">Open the Reel</button><button class="btn" data-g="pulse">The Pulse</button><button class="btn" data-g="lens">Choose a lens</button><button class="btn" data-g="close">Just browse</button></div></div>`;document.body.appendChild(g);requestAnimationFrame(()=>g.classList.add('on'));const guideOpener=rememberOpener(g);setInert(true);focusEl($('[data-g]',g));g.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();done();}else trapTab(e,g);});const done=()=>{store.set('seen',true);g.classList.remove('on');setInert($('#drawer').classList.contains('on')||!!(window.__REEL&&window.__REEL.isOpen()));setTimeout(()=>g.remove(),300); /* the page stays inert if a drawer or the Reel is still open over it */if(g.contains(document.activeElement))returnFocus(guideOpener);};$$('[data-g]',g).forEach(b=>b.addEventListener('click',()=>{const k=b.dataset.g;done();if(k==='reel')openReelHere(0);else if(k==='pulse')go('pulse');else if(k==='lens')openLens();}));g.addEventListener('click',e=>{if(e.target===g)done();});}
/* the one repair the static shell still needs: the document language, when the host's skeleton does not set it (page.html carries the rest) */
function fixShell(){const de=document.documentElement;if(!de.getAttribute('lang'))de.setAttribute('lang','en');}
/* the inline nav must end before the tools: measured after the fonts load and on resize; when it would not, it folds into the menu */
function fitNav(){const n=$('#nav'),t=$('.tools'),b=document.body;if(!n||!t)return;const was=b.classList.contains('navtight');b.classList.remove('navtight');
  if(getComputedStyle(n).position!=='fixed'&&getComputedStyle(n).display!=='none'){const last=n.lastElementChild;if(last&&last.getBoundingClientRect().right>t.getBoundingClientRect().left-4)b.classList.add('navtight');}
  if(was!==b.classList.contains('navtight')&&!b.classList.contains('navtight'))n.classList.remove('open');}
function start(){fixShell();initTheme();initPalette();initNav();fitNav();try{if(document.fonts&&document.fonts.ready)document.fonts.ready.then(fitNav);}catch(e){}$('#dClose').addEventListener('click',closeDrawer);$('#scrim').addEventListener('click',closeDrawer);
  if(!rendered.desk)renderView('desk');if(!rendered.salon)renderView('salon');
  route();booted=true;document.body.classList.add('booted');initCaps();let rt;window.addEventListener('resize',()=>{clearTimeout(rt);rt=setTimeout(()=>{fitNav();const t=$('#treemap');if(t&&current==='floor')treemap(t);
    /* the hammer board is rebuilt when the window crosses one of its width steps, so the title and the cells fit again */
    const b=$('#board');if(b&&boardWidth()!==BOARD.L){const i=BOARD.i;b.outerHTML=boardBuild();boardInit();boardShow(Math.min(i,BOARD.items.length-1));}
    /* the world map's labels are sized for the width it was drawn at: redrawn when it crosses a step */
    const wm=$('#world'),mb=window.innerWidth<600?0:window.innerWidth<900?1:2;if(wm&&wm.innerHTML&&wm.__mb!==mb&&typeof drawHubs==='function'){drawHubs();}   /* drawHubs records the width class it drew at */
    markScrollables($('.view.on'));},200);});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start();
